1	import React, { useEffect, useState, useCallback, useMemo } from 'react';
2	import { BoardItem, ConflictThreat, ExtensionMessage, GHLabel, LinkedPR, PRFile, RunwayConfig, RunwayData } from '../src/types';
3	import { ColumnGroup } from './components/ColumnGroup';
4	import { DetailPanel } from './components/DetailPanel';
5	import { LaunchpadView } from './components/LaunchpadView';
6	import { SettingsPanel } from './components/SettingsPanel';
7	
8	// Acquire vscode API once (must not be called more than once)
9	declare function acquireVsCodeApi(): {
10	  postMessage(msg: unknown): void;
11	  getState(): unknown;
12	  setState(state: unknown): void;
13	};
14	const vscodeApi = acquireVsCodeApi();
15	
16	type FilterTab = 'dashboard' | 'all' | 'prs' | 'issues' | 'milestones';
17	
18	// CSS is loaded externally via out/styles.css (see SprintHubPanel._buildHtml)
19	
20	
21	// Column metadata
22	const COLUMN_CONFIG: Record<string, { color: string; emoji: string }> = {
23	  'TODO':                  { color: '#585b70', emoji: '○' },
24	  'In Progress':           { color: '#89b4fa', emoji: '◑' },
25	  'Ready For Review':      { color: '#fab387', emoji: '👁' },
26	  'Ready For QA':          { color: '#f9e2af', emoji: '🔍' },
27	  'QA Done':               { color: '#a6e3a1', emoji: '✓' },
28	  'Done':                  { color: '#74c7ec', emoji: '✓✓' },
29	  'Blocked':               { color: '#f38ba8', emoji: '⊘' },
30	  'Needs Grooming':        { color: '#cba6f7', emoji: '✂' },
31	  'Grooming in Progress':  { color: '#b4befe', emoji: '⚙' },
32	  'Grooming to Review':    { color: '#f5c2e7', emoji: '⬡' },
33	};
34	
35	function getColumnConfig(name: string) {
36	  return COLUMN_CONFIG[name] ?? { color: '#6c7086', emoji: '·' };
37	}
38	
39	// ── Lightweight markdown renderer for the standup output ──────────────────────
40	// Only handles the exact patterns generated by generateStandupMarkdown.
41	
42	function parseInlineMarkdown(text: string, onOpenUrl: (url: string) => void, key: string): React.ReactNode {
43	  const nodes: React.ReactNode[] = [];
44	  const linkRe = /\[([^\]]+)\]\(([^)]+)\)/g;
45	  let cursor = 0;
46	  let m: RegExpExecArray | null;
47	
48	  while ((m = linkRe.exec(text)) !== null) {
49	    if (m.index > cursor) {
50	      nodes.push(parseItalic(text.slice(cursor, m.index), `${key}-t${cursor}`));
51	    }
52	    const url = m[2];
53	    nodes.push(
54	      <a key={`${key}-l${m.index}`} href="#" className="standup-link"
55	        onClick={(e) => { e.preventDefault(); onOpenUrl(url); }}>
56	        {m[1]}
57	      </a>
58	    );
59	    cursor = m.index + m[0].length;
60	  }
61	  if (cursor < text.length) nodes.push(parseItalic(text.slice(cursor), `${key}-t${cursor}`));
62	  return nodes.length === 1 ? nodes[0] : <React.Fragment key={key}>{nodes}</React.Fragment>;
63	}
64	
65	function parseItalic(text: string, key: string): React.ReactNode {
66	  const nodes: React.ReactNode[] = [];
67	  const re = /\*([^*]+)\*/g;
68	  let cursor = 0;
69	  let m: RegExpExecArray | null;
70	  while ((m = re.exec(text)) !== null) {
71	    if (m.index > cursor) nodes.push(text.slice(cursor, m.index));
72	    nodes.push(<em key={`${key}-i${m.index}`} className="standup-em">{m[1]}</em>);
73	    cursor = m.index + m[0].length;
74	  }
75	  if (cursor < text.length) nodes.push(text.slice(cursor));
76	  return nodes.length === 0 ? text : nodes.length === 1 ? nodes[0] : <React.Fragment key={key}>{nodes}</React.Fragment>;
77	}
78	
79	function renderStandupMarkdown(md: string, onOpenUrl: (url: string) => void): React.ReactNode {
80	  const lines = md.split('\n');
81	  const els: React.ReactNode[] = [];
82	  for (let i = 0; i < lines.length; i++) {
83	    const line = lines[i];
84	    if (line.startsWith('## ')) {
85	      els.push(<h2 key={i} className="standup-h2">{line.slice(3)}</h2>);
86	    } else if (line.startsWith('### ')) {
87	      els.push(<h3 key={i} className="standup-h3">{parseInlineMarkdown(line.slice(4), onOpenUrl, `${i}`)}</h3>);
88	    } else if (line.startsWith('- ')) {
89	      els.push(
90	        <div key={i} className="standup-li">
91	          <span className="standup-bullet">•</span>
92	          <span>{parseInlineMarkdown(line.slice(2), onOpenUrl, `${i}`)}</span>
93	        </div>
94	      );
95	    } else if (line.trim() === '') {
96	      els.push(<div key={i} className="standup-spacer" />);
97	    } else {
98	      els.push(<p key={i} className="standup-p">{parseInlineMarkdown(line, onOpenUrl, `${i}`)}</p>);
99	    }
100	  }
101	  return <div className="standup-rendered">{els}</div>;
102	}
103	
104	// ──────────────────────────────────────────────────────────────────────────────
105	
106	function useDebounce<T>(value: T, delay: number): T {
107	  const [debounced, setDebounced] = useState(value);
108	  useEffect(() => {
109	    const id = setTimeout(() => setDebounced(value), delay);
110	    return () => clearTimeout(id);
111	  }, [value, delay]);
112	  return debounced;
113	}
114	
115	export function App() {
116	  const [state, setState] = useState<'loading' | 'error' | 'data'>('loading');
117	  const [data, setData] = useState<RunwayData | null>(null);
118	  const [config, setConfig] = useState<RunwayConfig | null>(null);
119	  const [errorMsg, setErrorMsg] = useState('');
120	  const [isRefreshing, setIsRefreshing] = useState(false);
121	  const [search, setSearch] = useState('');
122	  const debouncedSearch = useDebounce(search, 150);
123	  const [tab, setTab] = useState<FilterTab>('dashboard');
124	  const [sprintFilter, setSprintFilter] = useState<string | null>(() => {
125	    const saved = vscodeApi.getState() as { sprintFilter?: string | null } | undefined;
126	    return saved?.sprintFilter ?? null;
127	  });
128	  // Auto-select the first sprint only on the very first data load (when the user
129	  // has never interacted with the sprint picker). Once the user explicitly sets
130	  // or clears the filter it should never be overridden by a background refresh.
131	  const sprintNeedsAutoSelect = React.useRef(
132	    (vscodeApi.getState() as { sprintFilter?: string | null } | undefined)?.sprintFilter === undefined
133	  );
134	  const [detailItem, setDetailItem] = useState<BoardItem | null>(null);
135	  const [linkedPRs, setLinkedPRs] = useState<LinkedPR[] | null>(null);
136	  const [settingsOpen, setSettingsOpen] = useState(false);
137	  const [settingsOwners, setSettingsOwners] = useState<Array<{ login: string; ownerType: 'organization' | 'user' }> | null>(null);
138	  const [settingsProjects, setSettingsProjects] = useState<Array<{ number: number; title: string }> | null>(null);
139	  // Phase 1: PR file deep linking
140	  const [prFiles, setPrFiles] = useState<PRFile[] | null>(null);
141	  // Phase 2: conflict threats
142	  const [conflictThreats, setConflictThreats] = useState<ConflictThreat[]>([]);
143	  // Phase 3: standup
144	  const [standupMarkdown, setStandupMarkdown] = useState<string | null>(null);
145	  const [standupLoading, setStandupLoading] = useState(false);
146	  const [standupView, setStandupView] = useState<'view' | 'markdown'>('view');
147	  // Phase 3: repo labels cache keyed by "owner/repo"
148	  const [repoLabelsCache, setRepoLabelsCache] = useState<Map<string, GHLabel[]>>(new Map());
149	  // v2: CODEOWNERS cache keyed by "owner/repo"
150	  const [codeownersCache, setCodeownersCache] = useState<Map<string, Array<{ pattern: string; owners: string[] }>>>(new Map());
151	  // Body cache keyed by "itemId:updatedAt" — a changed updatedAt is a cache miss,
152	  // so board refreshes automatically invalidate stale bodies without a full wipe.
153	  const itemBodyCache = React.useRef<Map<string, string>>(new Map());
154	  // Tracks the last fetchBody key sent to avoid duplicate requests when
155	  // handleSelectItem and the stale-body useEffect both fire for the same item.
156	  const lastBodyFetchKey = React.useRef<string | null>(null);
157	
158	  useEffect(() => {
159	    const handler = (event: MessageEvent) => {
160	      const msg = event.data as ExtensionMessage;
161	      switch (msg.type) {
162	        case 'loading':
163	          setIsRefreshing(true);
164	          if (state !== 'data') setState('loading');
165	          break;
166	        case 'data': {
167	          setData(msg.payload);
168	          setState('data');
169	          setIsRefreshing(false);
170	          // Validate the restored sprint filter against the incoming sprint list.
171	          // A stale value (different project or archived sprint) is reset to the
172	          // latest sprint so the board never silently hides all cards.
173	          // Auto-select only fires once (first-ever data load); after that we
174	          // respect whatever the user set, including an explicit null ("show all").
175	          const autoSelect = sprintNeedsAutoSelect.current;
176	          if (autoSelect) sprintNeedsAutoSelect.current = false;
177	          setSprintFilter((prev) => {
178	            if (msg.payload.sprints.length === 0) return null;
179	            if (prev !== null) {
180	              // Keep a valid selection; reset a stale one to the first sprint.
181	              return msg.payload.sprints.includes(prev) ? prev : msg.payload.sprints[0];
182	            }
183	            // prev === null: first-ever load → auto-select; otherwise user chose "show all"
184	            return autoSelect ? msg.payload.sprints[0] : null;
185	          });
186	          // Keep the open detail panel in sync with refreshed board data.
187	          // Scan groups with early exit instead of flattening to avoid
188	          // unnecessary allocations on large boards.
189	          setDetailItem((prev) => {
190	            if (!prev) return prev;
191	            for (const col of Object.values(msg.payload.groups)) {
192	              const updated = col.find((i) => i.id === prev.id);
193	              if (updated) {
194	                // updatedAt changed → drop stale body so the useEffect below re-fetches
195	                return updated.updatedAt !== prev.updatedAt
196	                  ? { ...updated }
197	                  : { ...updated, body: prev.body };
198	              }
199	            }
200	            const linkedPR = (msg.payload.linkedIssuePRs ?? []).find((i) => i.id === prev.id);
201	            if (linkedPR) return { ...linkedPR, body: prev.body };
202	            // Item absent from the full payload — closed/merged/removed; close the panel
203	            return null;
204	          });
205	          break;
206	        }
207	        case 'error':
208	          setErrorMsg(msg.message);
209	          setState('error');
210	          setIsRefreshing(false);
211	          break;
212	        case 'config':
213	          setConfig(msg.payload);
214	          break;
215	        case 'linkedPRs':
216	          setLinkedPRs(msg.prs);
217	          break;
218	        case 'itemBody':
219	          // null = transient fetch failure; skip caching so next open retries
220	          if (msg.body !== null) {
221	            itemBodyCache.current.set(`${msg.itemId}:${msg.updatedAt}`, msg.body);
222	          }
223	          setDetailItem((prev) =>
224	            prev && prev.id === msg.itemId
225	              ? { ...prev, body: msg.body ?? undefined }
226	              : prev
227	          );
228	          break;
229	        // Phase 1: PR files
230	        case 'prFiles':
231	          setPrFiles(msg.files);
232	          break;
233	        // Phase 2: conflict threats
234	        case 'conflictThreats':
235	          setConflictThreats(msg.threats);
236	          break;
