423	    try {
424	      const prFilesMap = await fetchAllOpenPRFiles(openPRs.map((p) => ({ owner: p.owner, repo: p.repo, number: p.number })));
425	      const threats: ConflictThreat[] = [];
426	
427	      for (const pr of openPRs) {
428	        const key = `${pr.owner}/${pr.repo}#${pr.number}`;
429	        const files = prFilesMap.get(key) ?? [];
430	        for (const file of files) {
431	          if (localDirty.has(file.filename)) {
432	            threats.push({
433	              filename: file.filename,
434	              prNumber: pr.number,
435	              prTitle: pr.title,
436	              prAuthor: pr.author,
437	              prUrl: pr.url,
438	            });
439	          }
440	        }
441	      }
442	
443	      this._post({ type: 'conflictThreats', threats });
444	    } catch {
445	      // conflict check is best-effort
446	    }
447	  }
448	
449	  // ─── Phase 2: Status Bar Blocker Watchdog ──────────────────────────────────
450	
451	  private _updateStatusBar(data: RunwayData) {
452	    const allItems: BoardItem[] = [...Object.values(data.groups).flat(), ...(data.linkedIssuePRs ?? [])];
453	    const openPRs = allItems.filter((i) => i.type === 'PULL_REQUEST' && i.state === 'OPEN');
454	
455	    const ciFailures = openPRs.filter((i) => i.ciState === 'FAILURE' || i.ciState === 'ERROR');
456	    const changesRequested = openPRs.filter((i) =>
457	      i.reviews?.some((r) => r.state === 'CHANGES_REQUESTED')
458	    );
459	
460	    const total = ciFailures.length + changesRequested.length;
461	
462	    if (total === 0) {
463	      this._statusBarItem.text = '$(check) SprintHub';
464	      this._statusBarItem.backgroundColor = undefined;
465	    } else {
466	      const parts: string[] = [];
467	      if (ciFailures.length) parts.push(`${ciFailures.length} CI fail${ciFailures.length > 1 ? 's' : ''}`);
468	      if (changesRequested.length) parts.push(`${changesRequested.length} changes req`);
469	      this._statusBarItem.text = `$(warning) ${parts.join(' · ')}`;
470	      this._statusBarItem.backgroundColor = new vscode.ThemeColor('statusBarItem.warningBackground');
471	    }
472	
473	    this._statusBarItem.show();
474	
475	    // Store for use in showBlockers quick-pick
476	    (this as unknown as Record<string, unknown>)._blockerPRs = { ciFailures, changesRequested };
477	  }
478	
479	  public showBlockersQuickPick() {
480	    const stored = (this as unknown as Record<string, unknown>)._blockerPRs as
481	      | { ciFailures: BoardItem[]; changesRequested: BoardItem[] }
482	      | undefined;
483	    if (!stored) {
484	      vscode.window.showInformationMessage('SprintHub: No blocker data loaded yet.');
485	      return;
486	    }
487	
488	    const { ciFailures, changesRequested } = stored;
489	    const items: vscode.QuickPickItem[] = [];
490	
491	    if (ciFailures.length) {
492	      items.push({ label: '$(error) CI Failing', kind: vscode.QuickPickItemKind.Separator });
493	      for (const pr of ciFailures) {
494	        items.push({ label: `#${pr.number} ${pr.title}`, description: `${pr.repositoryOwner}/${pr.repository}`, detail: pr.url });
495	      }
496	    }
497	
498	    if (changesRequested.length) {
499	      items.push({ label: '$(git-pull-request) Changes Requested', kind: vscode.QuickPickItemKind.Separator });
500	      for (const pr of changesRequested) {
501	        items.push({ label: `#${pr.number} ${pr.title}`, description: `${pr.repositoryOwner}/${pr.repository}`, detail: pr.url });
502	      }
503	    }
504	
505	    if (!items.length) {
506	      vscode.window.showInformationMessage('SprintHub: All PRs are healthy!');
507	      return;
508	    }
509	
510	    void vscode.window.showQuickPick(items, { title: 'SprintHub Blockers', placeHolder: 'Select a PR to open on GitHub' }).then((selected) => {
511	      if (selected?.detail) {
512	        void vscode.env.openExternal(vscode.Uri.parse(selected.detail));
513	      }
514	    });
515	  }
516	
517	  // ─── Phase 3: Standup Markdown Generator ───────────────────────────────────
518	
519	  private async _generateStandup(viewerLogin: string) {
520	    try {
521	      const markdown = await generateStandupMarkdown(viewerLogin);
522	      this._post({ type: 'standup', markdown });
523	    } catch (err) {
524	      const msg = err instanceof Error ? err.message : String(err);
525	      this._post({ type: 'standup', markdown: `*Error generating standup: ${msg}*` });
526	    }
527	  }
528	
529	  // ─── Phase 3: Metadata Sync ─────────────────────────────────────────────────
530	
531	  private async _updateMetadata(
532	    itemId: string,
533	    owner: string,
534	    repo: string,
535	    issueNumber: number,
536	    labels?: string[],
537	    assignees?: string[]
538	  ) {
539	    try {
540	      const updated = await updateIssueMetadata(owner, repo, issueNumber, labels, assignees);
541	      this._post({ type: 'metadataUpdated', itemId, labels: updated.labels, assignees: updated.assignees });
542	    } catch (err) {
543	      const msg = err instanceof Error ? err.message : String(err);
544	      vscode.window.showErrorMessage(`SprintHub: Failed to update metadata — ${msg}`);
545	    }
546	  }
547	
548	  private async _fetchRepoLabels(owner: string, repo: string) {
549	    try {
550	      const labels = await fetchRepoLabels(owner, repo);
551	      this._post({ type: 'repoLabels', owner, repo, labels });
552	    } catch {
553	      this._post({ type: 'repoLabels', owner, repo, labels: [] });
554	    }
555	  }
556	
557	  // ─── v2 extras ───────────────────────────────────────────────────────────────
558	
559	  private async _convertDraftToReady(itemId: string, owner: string, repo: string, prNumber: number) {
560	    try {
561	      await convertDraftToReady(owner, repo, prNumber);
562	      this._post({ type: 'prReadied', itemId });
563	    } catch (err) {
564	      vscode.window.showErrorMessage(`SprintHub: ${err instanceof Error ? err.message : String(err)}`);
565	    }
566	  }
567	
568	  private async _mergePR(
569	    itemId: string,
570	    owner: string,
571	    repo: string,
572	    prNumber: number,
573	    mergeMethod: 'merge' | 'squash' | 'rebase'
574	  ) {
575	    try {
576	      await mergePR(owner, repo, prNumber, mergeMethod);
577	      this._post({ type: 'prMerged', itemId });
578	      vscode.window.showInformationMessage(`SprintHub: PR #${prNumber} merged successfully.`);
579	    } catch (err) {
580	      vscode.window.showErrorMessage(`SprintHub: ${err instanceof Error ? err.message : String(err)}`);
581	    }
582	  }
583	
584	  private async _fetchCodeowners(owner: string, repo: string) {
585	    try {
586	      const entries = await fetchCodeowners(owner, repo);
587	      this._post({ type: 'codeowners', owner, repo, entries });
588	    } catch {
589	      this._post({ type: 'codeowners', owner, repo, entries: [] });
590	    }
591	  }
592	
593	  private async _fetchSettingsOwners() {
594	    try {
595	      const owners = await fetchSettingsOwners();
596	      this._post({ type: 'settingsOwners', owners });
597	    } catch {
598	      this._post({ type: 'settingsOwners', owners: [] });
599	    }
600	  }
601	
602	  private async _fetchSettingsProjects(owner: string, ownerType: 'organization' | 'user') {
603	    try {
604	      const projects = await fetchSettingsProjects(owner, ownerType);
605	      this._post({ type: 'settingsProjects', projects });
606	    } catch {
607	      this._post({ type: 'settingsProjects', projects: [] });
608	    }
609	  }
610	
611	  // ───────────────────────────────────────────────────────────────────────────
612	
613	  private _post(message: ExtensionMessage) {
614	    this._panel.webview.postMessage(message);
615	  }
616	
617	  private _buildHtml(webview: vscode.Webview): string {
618	    const scriptUri = webview.asWebviewUri(
619	      vscode.Uri.joinPath(this._extensionUri, 'out', 'webview.js')
620	    );
621	    const stylesUri = webview.asWebviewUri(
622	      vscode.Uri.joinPath(this._extensionUri, 'out', 'styles.css')
623	    );
624	    const nonce = getNonce();
625	
626	    return /* html */ `<!DOCTYPE html>
627	<html lang="en">
628	<head>
629	  <meta charset="UTF-8">
630	  <meta name="viewport" content="width=device-width, initial-scale=1.0">
631	  <meta http-equiv="Content-Security-Policy"
632	    content="default-src 'none';
633	             img-src ${webview.cspSource} https: data:;
634	             script-src 'nonce-${nonce}';
635	             style-src ${webview.cspSource} 'unsafe-inline';">
636	  <title>SprintHub</title>
637	  <link rel="stylesheet" href="${stylesUri}">
638	</head>
639	<body>
640	  <div id="root"></div>
641	  <script nonce="${nonce}" src="${scriptUri}"></script>
642	</body>
643	</html>`;
644	  }
645	
646	  public dispose() {
647	    SprintHubPanel.currentPanel = undefined;
648	    if (this._refreshTimer) {
649	      clearInterval(this._refreshTimer);
650	    }
651	    this._statusBarItem.hide();
652	    this._panel.dispose();
653	    while (this._disposables.length) {
654	      const d = this._disposables.pop();
655	      if (d) d.dispose();
656	    }
657	  }
658	}
