  | { type: 'mergePR'; itemId: string; owner: string; repo: string; prNumber: number; mergeMethod: 'merge' | 'squash' | 'rebase' }
  | { type: 'fetchCodeowners'; owner: string; repo: string }
  // Settings pickers
