1	import * as vscode from 'vscode';
2	import * as cp from 'child_process';
3	import * as util from 'util';
4	import {
5	  fetchProjectData,
6	  fetchLinkedPRChecks,
7	  fetchItemBody,
8	  fetchPRFiles,
9	  fetchAllOpenPRFiles,
10	  generateStandupData,
11	  updateIssueMetadata,
12	  fetchRepoLabels,
13	  convertDraftToReady,
14	  mergePR,
15	  fetchCodeowners,
16	  fetchSettingsOwners,
17	  fetchSettingsProjects,
18	} from './githubService';
19	import { BoardItem, ConflictThreat, ExtensionMessage, RunwayConfig, RunwayData, WebviewMessage } from './types';
20	
21	const exec = util.promisify(cp.exec);
22	
23	function getNonce() {
24	  let text = '';
25	  const chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789';
26	  for (let i = 0; i < 32; i++) {
27	    text += chars.charAt(Math.floor(Math.random() * chars.length));
28	  }
29	  return text;
30	}
31	
32	export class SprintHubPanel {
33	  public static currentPanel: SprintHubPanel | undefined;
34	  private static readonly viewType = 'sprinthub';
35	
36	  private readonly _panel: vscode.WebviewPanel;
37	  private readonly _extensionUri: vscode.Uri;
38	  private readonly _disposables: vscode.Disposable[] = [];
39	  private _refreshTimer: ReturnType<typeof setInterval> | undefined;
40	  private _statusBarItem: vscode.StatusBarItem;
41	  private _lastData: RunwayData | undefined;
42	
43	  public static createOrShow(extensionUri: vscode.Uri) {
44	    const column = vscode.window.activeTextEditor
45	      ? vscode.window.activeTextEditor.viewColumn
46	      : undefined;
47	
48	    if (SprintHubPanel.currentPanel) {
49	      SprintHubPanel.currentPanel._panel.reveal(column);
50	      return;
51	    }
52	
53	    const panel = vscode.window.createWebviewPanel(
54	      SprintHubPanel.viewType,
55	      'SprintHub',
56	      column ?? vscode.ViewColumn.One,
57	      {
58	        enableScripts: true,
59	        retainContextWhenHidden: true,
60	        localResourceRoots: [vscode.Uri.joinPath(extensionUri, 'out')],
61	      }
62	    );
63	
64	    SprintHubPanel.currentPanel = new SprintHubPanel(panel, extensionUri);
65	  }
66	
67	  private constructor(panel: vscode.WebviewPanel, extensionUri: vscode.Uri) {
68	    this._panel = panel;
69	    this._extensionUri = extensionUri;
70	
71	    // Phase 2: Status bar blocker watchdog
72	    this._statusBarItem = vscode.window.createStatusBarItem(vscode.StatusBarAlignment.Right, 100);
73	    this._statusBarItem.command = 'sprinthub.showBlockers';
74	    this._statusBarItem.tooltip = 'SprintHub — CI & review status';
75	    this._disposables.push(this._statusBarItem);
76	
77	    this._panel.webview.html = this._buildHtml(this._panel.webview);
78	
79	    this._panel.onDidDispose(() => this.dispose(), null, this._disposables);
80	
81	    this._panel.webview.onDidReceiveMessage(
82	      (message: WebviewMessage) => {
83	        switch (message.type) {
84	          case 'refresh':
85	            this._loadData();
86	            break;
87	          case 'openUrl':
88	            vscode.env.openExternal(vscode.Uri.parse(message.url));
89	            break;
90	          case 'getConfig':
91	            this._sendConfig();
92	            break;
93	          case 'updateConfig':
94	            void this._updateConfig(message.payload);
95	            break;
96	          case 'fetchLinkedPRs':
97	            void this._fetchLinkedPRs(message.itemId, message.owner, message.repo, message.issueNumber);
98	            break;
99	          case 'fetchBody':
100	            void this._fetchBody(message.itemId, message.owner, message.repo, message.number, message.isIssue, message.updatedAt);
101	            break;
102	          // Phase 1: Work-On-This Engine
103	          case 'workOnThis':
104	            void this._workOnThis(message.branchName, message.owner, message.repo);
105	            break;
106	          // Phase 1: File-Level Deep Linking
107	          case 'fetchPRFiles':
108	            void this._fetchPRFiles(message.prKey, message.owner, message.repo, message.prNumber);
109	            break;
110	          case 'openPRFile':
111	            void this._openPRFile(message.owner, message.repo, message.prNumber, message.filename, message.patch);
112	            break;
113	          // Phase 3: Standup Generator
114	          case 'generateStandup':
115	            void this._generateStandup(message.viewerLogin);
116	            break;
117	          // Phase 3: Metadata Sync
118	          case 'updateMetadata':
119	            void this._updateMetadata(message.itemId, message.owner, message.repo, message.issueNumber, message.labels, message.assignees);
120	            break;
121	          case 'fetchRepoLabels':
122	            void this._fetchRepoLabels(message.owner, message.repo);
123	            break;
124	          case 'convertDraftToReady':
125	            void this._convertDraftToReady(message.itemId, message.owner, message.repo, message.prNumber);
126	            break;
127	          case 'mergePR':
128	            void this._mergePR(message.itemId, message.owner, message.repo, message.prNumber, message.mergeMethod);
129	            break;
130	          case 'fetchCodeowners':
131	            void this._fetchCodeowners(message.owner, message.repo);
132	            break;
133	          case 'fetchSettingsOwners':
134	            void this._fetchSettingsOwners();
135	            break;
136	          case 'fetchSettingsProjects':
137	            void this._fetchSettingsProjects(message.owner, message.ownerType);
138	            break;
139	          // Phase 1: Work-On-This Engine
140	          case 'workOnThis':
141	            void this._workOnThis(message.branchName, message.owner, message.repo);
142	            break;
143	          // Phase 1: File-Level Deep Linking
144	          case 'fetchPRFiles':
145	            void this._fetchPRFiles(message.prKey, message.owner, message.repo, message.prNumber);
146	            break;
147	          case 'openPRFile':
148	            void this._openPRFile(message.owner, message.repo, message.prNumber, message.filename, message.patch);
149	            break;
150	          // Phase 3: Standup Generator
151	          case 'generateStandup':
152	            void this._generateStandup(message.viewerLogin);
153	            break;
154	          // Phase 3: Metadata Sync
155	          case 'updateMetadata':
156	            void this._updateMetadata(message.itemId, message.owner, message.repo, message.issueNumber, message.labels, message.assignees);
157	            break;
158	          case 'fetchRepoLabels':
159	            void this._fetchRepoLabels(message.owner, message.repo);
160	            break;
161	          case 'convertDraftToReady':
162	            void this._convertDraftToReady(message.itemId, message.owner, message.repo, message.prNumber);
163	            break;
164	          case 'mergePR':
165	            void this._mergePR(message.itemId, message.owner, message.repo, message.prNumber, message.mergeMethod);
166	            break;
167	          case 'fetchCodeowners':
168	            void this._fetchCodeowners(message.owner, message.repo);
169	            break;
170	        }
171	      },
172	      null,
173	      this._disposables
174	    );
175	
176	    vscode.workspace.onDidChangeConfiguration(
177	      (e) => {
178	        if (e.affectsConfiguration('sprinthub')) {
179	          this._sendConfig();
180	          // Only reload data when a field that affects the API query changes.
181	          // Cosmetic fields (liquidGlass, theme, colorBlind) and refreshInterval
182	          // must not trigger a full board re-fetch.
183	          const dataFields = ['owner', 'projectNumber', 'ownerType', 'statusFieldName'];
184	          if (dataFields.some((f) => e.affectsConfiguration(`sprinthub.${f}`))) {
185	            this._loadData();
186	          }
187	          this._scheduleRefresh();
188	        }
189	      },
190	      null,
191	      this._disposables
192	    );
193	
194	    this._loadData();
195	    this._sendConfig();
196	    this._scheduleRefresh();
197	  }
198	
199	  private _sendConfig() {
200	    const config = vscode.workspace.getConfiguration('sprinthub');
201	    const payload: RunwayConfig = {
202	      owner: config.get<string>('owner', '').trim(),
203	      projectNumber: config.get<number>('projectNumber', 0),
204	      ownerType: config.get<string>('ownerType', 'organization') as 'organization' | 'user',
205	      statusFieldName: config.get<string>('statusFieldName', 'Status'),
206	      refreshInterval: config.get<number>('refreshInterval', 5),
207	      liquidGlass: config.get<boolean>('liquidGlass', true),
208	      theme: config.get<string>('theme', 'dark') as 'dark' | 'light',
209	      colorBlind: config.get<boolean>('colorBlind', false),
210	    };
211	    this._post({ type: 'config', payload });
212	  }
213	
214	  private async _updateConfig(cfg: RunwayConfig) {
215	    const config = vscode.workspace.getConfiguration('sprinthub');
216	    await Promise.all([
217	      config.update('owner', cfg.owner, vscode.ConfigurationTarget.Global),
218	      config.update('projectNumber', cfg.projectNumber, vscode.ConfigurationTarget.Global),
219	      config.update('ownerType', cfg.ownerType, vscode.ConfigurationTarget.Global),
220	      config.update('statusFieldName', cfg.statusFieldName, vscode.ConfigurationTarget.Global),
221	      config.update('refreshInterval', cfg.refreshInterval, vscode.ConfigurationTarget.Global),
222	      config.update('liquidGlass', cfg.liquidGlass, vscode.ConfigurationTarget.Global),
223	      config.update('theme', cfg.theme, vscode.ConfigurationTarget.Global),
224	      config.update('colorBlind', cfg.colorBlind, vscode.ConfigurationTarget.Global),
225	    ]);
226	  }
227	
228	  private async _fetchLinkedPRs(itemId: string, owner: string, repo: string, issueNumber: number) {
229	    const timeout = new Promise<never>((_, reject) =>
230	      setTimeout(() => reject(new Error('timeout')), 15000)
231	    );
232	    try {
233	      const prs = await Promise.race([fetchLinkedPRChecks(owner, repo, issueNumber), timeout]);
234	      this._post({ type: 'linkedPRs', itemId, prs });
235	    } catch {
236	      this._post({ type: 'linkedPRs', itemId, prs: [] });
237	    }
238	  }
239	
240	  private async _fetchBody(itemId: string, owner: string, repo: string, number: number, isIssue: boolean, updatedAt: string) {
241	    try {
242	      const body = await fetchItemBody(owner, repo, number, isIssue);
243	      this._post({ type: 'itemBody', itemId, body, updatedAt });
244	    } catch {
245	      // null signals a transient failure — the webview will not cache it so the
246	      // next open will retry rather than permanently showing an empty body.
247	      this._post({ type: 'itemBody', itemId, body: null, updatedAt });
248	    }
249	  }
250	
251	  private _scheduleRefresh() {
252	    if (this._refreshTimer) {
253	      clearInterval(this._refreshTimer);
254	    }
255	    const intervalMinutes =
256	      vscode.workspace.getConfiguration('sprinthub').get<number>('refreshInterval', 5);
257	    if (intervalMinutes > 0) {
258	      this._refreshTimer = setInterval(
259	        () => this._loadData(),
260	        intervalMinutes * 60 * 1000
261	      );
262	    }
263	  }
264	
265	  private async _loadData() {
266	    this._post({ type: 'loading' });
267	
268	    const config = vscode.workspace.getConfiguration('sprinthub');
269	    const owner = config.get<string>('owner', '').trim();
270	    const projectNumber = config.get<number>('projectNumber', 0);
271	    const ownerType = config.get<string>('ownerType', 'organization');
272	    const statusFieldName = config.get<string>('statusFieldName', 'Status');
273	
274	    if (!owner || !projectNumber) {
275	      this._post({
276	        type: 'error',
277	        message:
278	          'Please set sprinthub.owner and sprinthub.projectNumber in your VS Code settings (File → Preferences → Settings → search "SprintHub").',
279	      });
280	      return;
281	    }
282	
283	    try {
284	      const data = await fetchProjectData(
285	        owner,
286	        projectNumber,
287	        ownerType === 'organization',
288	        statusFieldName
289	      );
290	      this._lastData = data;
291	      this._post({ type: 'data', payload: data });
292	      this._updateStatusBar(data);
293	      // Phase 2: run conflict check in background after data loads
294	      void this._checkConflicts(data);
295	    } catch (err: unknown) {
296	      const msg = err instanceof Error ? err.message : String(err);
297	      this._post({ type: 'error', message: msg });
298	    }
299	  }
300	
301	  // ─── Phase 1: Work-On-This Engine ──────────────────────────────────────────
302	
303	  private async _workOnThis(branchName: string, _owner: string, _repo: string) {
304	    const cwd = vscode.workspace.workspaceFolders?.[0]?.uri.fsPath;
305	    if (!cwd) {
306	      vscode.window.showErrorMessage('SprintHub: No workspace folder open to checkout branch.');
307	      return;
308	    }
309	
310	    let branchExists = false;
311	    try {
312	      await exec(`git rev-parse --verify "${branchName}"`, { cwd });
313	      branchExists = true;
314	    } catch {
315	      branchExists = false;
316	    }
317	
318	    let terminal = vscode.window.terminals.find((t) => t.name === 'SprintHub');
319	    if (!terminal) {
320	      terminal = vscode.window.createTerminal('SprintHub');
321	    }
322	    terminal.show(true);
323	
324	    if (branchExists) {
325	      terminal.sendText(`git checkout ${branchName}`);
326	    } else {
327	      terminal.sendText(`git fetch origin ${branchName} 2>/dev/null; git checkout -b ${branchName} origin/${branchName} 2>/dev/null || git checkout ${branchName}`);
328	    }
329	
330	    // Focus the most recently modified file in the workspace
331	    setTimeout(() => void this._focusMostRecentFile(cwd), 2000);
332	  }
333	
334	  private async _focusMostRecentFile(cwd: string) {
335	    try {
336	      const { stdout } = await exec('git diff --name-only HEAD', { cwd });
337	      const files = stdout.trim().split('\n').filter(Boolean);
338	      if (!files.length) return;
339	      const found = await vscode.workspace.findFiles(files[0], '**/node_modules/**', 1);
340	      if (found.length) {
341	        const doc = await vscode.workspace.openTextDocument(found[0]);
342	        await vscode.window.showTextDocument(doc, { preserveFocus: false });
343	      }
344	    } catch {
345	      // silently skip if git diff fails (detached HEAD, etc.)
346	    }
347	  }
348	
349	  // ─── Phase 1: File-Level Deep Linking ──────────────────────────────────────
350	
351	  private async _fetchPRFiles(prKey: string, owner: string, repo: string, prNumber: number) {
352	    try {
353	      const files = await fetchPRFiles(owner, repo, prNumber);
354	      this._post({ type: 'prFiles', prKey, files });
355	    } catch {
356	      this._post({ type: 'prFiles', prKey, files: [] });
357	    }
358	  }
359	
360	  private async _openPRFile(owner: string, repo: string, _prNumber: number, filename: string, patch?: string) {
361	    const cwd = vscode.workspace.workspaceFolders?.[0]?.uri.fsPath;
362	    if (!cwd) {
363	      vscode.window.showWarningMessage('SprintHub: No workspace folder open.');
364	      return;
365	    }
366	
367	    const found = await vscode.workspace.findFiles(filename, '**/node_modules/**', 1);
368	    if (!found.length) {
369	      vscode.window.showWarningMessage(`SprintHub: File not found locally: ${filename}`);
370	      return;
371	    }
372	
373	    const doc = await vscode.workspace.openTextDocument(found[0]);
374	    let line = 0;
375	    if (patch) {
376	      const match = patch.match(/@@ -\d+(?:,\d+)? \+(\d+)/);
377	      if (match) line = Math.max(0, parseInt(match[1], 10) - 1);
378	    }
379	    const selection = new vscode.Range(line, 0, line, 0);
380	    await vscode.window.showTextDocument(doc, { selection });
381	  }
382	
383	  // ─── Phase 2: Hotspot Conflict Monitor ─────────────────────────────────────
384	
385	  private async _checkConflicts(data: RunwayData) {
386	    const cwd = vscode.workspace.workspaceFolders?.[0]?.uri.fsPath;
387	    if (!cwd) return;
388	
389	    let localDirty: Set<string>;
390	    try {
391	      const { stdout } = await exec('git diff --name-only HEAD', { cwd });
392	      localDirty = new Set(stdout.trim().split('\n').filter(Boolean));
393	    } catch {
394	      return;
395	    }
396	
397	    if (!localDirty.size) {
398	      this._post({ type: 'conflictThreats', threats: [] });
399	      return;
400	    }
401	
402	    // Collect open PRs from board + linked PRs
403	    const openPRs: Array<{ owner: string; repo: string; number: number; title: string; author: string; url: string }> = [];
404	    const allBoardItems: BoardItem[] = [...Object.values(data.groups).flat(), ...(data.linkedIssuePRs ?? [])];
405	    for (const item of allBoardItems) {
406	      if (item.type === 'PULL_REQUEST' && item.state === 'OPEN' && item.repositoryOwner && item.repository) {
407	        openPRs.push({
408	          owner: item.repositoryOwner,
409	          repo: item.repository,
410	          number: item.number,
411	          title: item.title,
412	          author: item.author.login,
413	          url: item.url,
414	        });
415	      }
416	    }
417	
418	    if (!openPRs.length) {
419	      this._post({ type: 'conflictThreats', threats: [] });
420	      return;
421	    }
422	
423	    try {
424	      const prFilesMap = await fetchAllOpenPRFiles(openPRs.map((p) => ({ owner: p.owner, repo: p.repo, number: p.number })));
425	      const threats: ConflictThreat[] = [];
426	
427	      for (const pr of openPRs) {
428	        const key = `${pr.owner}/${pr.repo}#${pr.number}`;
429	        const files = prFilesMap.get(key) ?? [];
430	        for (const file of files) {
431	          if (localDirty.has(file.filename)) {
432	            threats.push({
433	              filename: file.filename,
434	              prNumber: pr.number,
435	              prTitle: pr.title,
436	              prAuthor: pr.author,
437	              prUrl: pr.url,
438	            });
439	          }
440	        }
441	      }
442	
443	      this._post({ type: 'conflictThreats', threats });
444	    } catch {
445	      // conflict check is best-effort
446	    }
447	  }
448	
449	  // ─── Phase 2: Status Bar Blocker Watchdog ──────────────────────────────────
450	
451	  private _updateStatusBar(data: RunwayData) {
452	    const allItems: BoardItem[] = [...Object.values(data.groups).flat(), ...(data.linkedIssuePRs ?? [])];
453	    const openPRs = allItems.filter((i) => i.type === 'PULL_REQUEST' && i.state === 'OPEN');
454	
455	    const ciFailures = openPRs.filter((i) => i.ciState === 'FAILURE' || i.ciState === 'ERROR');
456	    const changesRequested = openPRs.filter((i) =>
457	      i.reviews?.some((r) => r.state === 'CHANGES_REQUESTED')
458	    );
459	
460	    const total = ciFailures.length + changesRequested.length;
461	
462	    if (total === 0) {
463	      this._statusBarItem.text = '$(check) SprintHub';
464	      this._statusBarItem.backgroundColor = undefined;
465	    } else {
466	      const parts: string[] = [];
467	      if (ciFailures.length) parts.push(`${ciFailures.length} CI fail${ciFailures.length > 1 ? 's' : ''}`);
468	      if (changesRequested.length) parts.push(`${changesRequested.length} changes req`);
469	      this._statusBarItem.text = `$(warning) ${parts.join(' · ')}`;
470	      this._statusBarItem.backgroundColor = new vscode.ThemeColor('statusBarItem.warningBackground');
471	    }
472	
473	    this._statusBarItem.show();
474	
475	    // Store for use in showBlockers quick-pick
476	    (this as unknown as Record<string, unknown>)._blockerPRs = { ciFailures, changesRequested };
477	  }
478	
479	  public showBlockersQuickPick() {
480	    const stored = (this as unknown as Record<string, unknown>)._blockerPRs as
481	      | { ciFailures: BoardItem[]; changesRequested: BoardItem[] }
482	      | undefined;
483	    if (!stored) {
484	      vscode.window.showInformationMessage('SprintHub: No blocker data loaded yet.');
485	      return;
486	    }
487	
488	    const { ciFailures, changesRequested } = stored;
489	    const items: vscode.QuickPickItem[] = [];
490	
491	    if (ciFailures.length) {
492	      items.push({ label: '$(error) CI Failing', kind: vscode.QuickPickItemKind.Separator });
493	      for (const pr of ciFailures) {
494	        items.push({ label: `#${pr.number} ${pr.title}`, description: `${pr.repositoryOwner}/${pr.repository}`, detail: pr.url });
495	      }
496	    }
497	
498	    if (changesRequested.length) {
499	      items.push({ label: '$(git-pull-request) Changes Requested', kind: vscode.QuickPickItemKind.Separator });
500	      for (const pr of changesRequested) {
501	        items.push({ label: `#${pr.number} ${pr.title}`, description: `${pr.repositoryOwner}/${pr.repository}`, detail: pr.url });
502	      }
503	    }
504	
505	    if (!items.length) {
506	      vscode.window.showInformationMessage('SprintHub: All PRs are healthy!');
507	      return;
508	    }
509	
510	    void vscode.window.showQuickPick(items, { title: 'SprintHub Blockers', placeHolder: 'Select a PR to open on GitHub' }).then((selected) => {
511	      if (selected?.detail) {
512	        void vscode.env.openExternal(vscode.Uri.parse(selected.detail));
513	      }
514	    });
515	  }
516	
517	  // ─── Phase 3: Standup Markdown Generator ───────────────────────────────────
518	
519	  private async _generateStandup(viewerLogin: string) {
520	    try {
521	      const { data, markdown } = await generateStandupData(viewerLogin);
522	      this._post({ type: 'standup', data, markdown });
523	    } catch (err) {
524	      const msg = err instanceof Error ? err.message : String(err);
525	      this._post({ type: 'standup', data: { date: '', sections: [] }, markdown: `*Error generating standup: ${msg}*` });
526	    }
527	  }
528	
529	  // ─── Phase 3: Metadata Sync ─────────────────────────────────────────────────
530	
531	  private async _updateMetadata(
532	    itemId: string,
533	    owner: string,
534	    repo: string,
535	    issueNumber: number,
536	    labels?: string[],
537	    assignees?: string[]
538	  ) {
539	    try {
540	      const updated = await updateIssueMetadata(owner, repo, issueNumber, labels, assignees);
541	      this._post({ type: 'metadataUpdated', itemId, labels: updated.labels, assignees: updated.assignees });
542	    } catch (err) {
543	      const msg = err instanceof Error ? err.message : String(err);
544	      vscode.window.showErrorMessage(`SprintHub: Failed to update metadata — ${msg}`);
545	    }
546	  }
547	
548	  private async _fetchRepoLabels(owner: string, repo: string) {
549	    try {
550	      const labels = await fetchRepoLabels(owner, repo);
551	      this._post({ type: 'repoLabels', owner, repo, labels });
552	    } catch {
553	      this._post({ type: 'repoLabels', owner, repo, labels: [] });
554	    }
555	  }
556	
557	  // ─── v2 extras ───────────────────────────────────────────────────────────────
558	
559	  private async _convertDraftToReady(itemId: string, owner: string, repo: string, prNumber: number) {
560	    try {
561	      await convertDraftToReady(owner, repo, prNumber);
562	      this._post({ type: 'prReadied', itemId });
563	    } catch (err) {
564	      vscode.window.showErrorMessage(`SprintHub: ${err instanceof Error ? err.message : String(err)}`);
565	    }
566	  }
567	
568	  private async _mergePR(
569	    itemId: string,
570	    owner: string,
571	    repo: string,
572	    prNumber: number,
573	    mergeMethod: 'merge' | 'squash' | 'rebase'
574	  ) {
575	    try {
576	      await mergePR(owner, repo, prNumber, mergeMethod);
577	      this._post({ type: 'prMerged', itemId });
578	      vscode.window.showInformationMessage(`SprintHub: PR #${prNumber} merged successfully.`);
579	    } catch (err) {
580	      vscode.window.showErrorMessage(`SprintHub: ${err instanceof Error ? err.message : String(err)}`);
581	    }
582	  }
583	
584	  private async _fetchCodeowners(owner: string, repo: string) {
585	    try {
586	      const entries = await fetchCodeowners(owner, repo);
587	      this._post({ type: 'codeowners', owner, repo, entries });
588	    } catch {
589	      this._post({ type: 'codeowners', owner, repo, entries: [] });
590	    }
591	  }
592	
593	  private async _fetchSettingsOwners() {
594	    try {
595	      const owners = await fetchSettingsOwners();
596	      this._post({ type: 'settingsOwners', owners });
597	    } catch {
598	      this._post({ type: 'settingsOwners', owners: [] });
599	    }
600	  }
601	
602	  private async _fetchSettingsProjects(owner: string, ownerType: 'organization' | 'user') {
603	    try {
604	      const projects = await fetchSettingsProjects(owner, ownerType);
605	      this._post({ type: 'settingsProjects', projects });
606	    } catch {
607	      this._post({ type: 'settingsProjects', projects: [] });
608	    }
609	  }
610	
611	  // ───────────────────────────────────────────────────────────────────────────
612	
613	  private _post(message: ExtensionMessage) {
614	    this._panel.webview.postMessage(message);
615	  }
616	
617	  private _buildHtml(webview: vscode.Webview): string {
618	    const scriptUri = webview.asWebviewUri(
619	      vscode.Uri.joinPath(this._extensionUri, 'out', 'webview.js')
620	    );
621	    const stylesUri = webview.asWebviewUri(
622	      vscode.Uri.joinPath(this._extensionUri, 'out', 'styles.css')
623	    );
624	    const nonce = getNonce();
625	
626	    return /* html */ `<!DOCTYPE html>
627	<html lang="en">
628	<head>
629	  <meta charset="UTF-8">
630	  <meta name="viewport" content="width=device-width, initial-scale=1.0">
631	  <meta http-equiv="Content-Security-Policy"
632	    content="default-src 'none';
633	             img-src ${webview.cspSource} https: data:;
634	             script-src 'nonce-${nonce}';
635	             style-src ${webview.cspSource} 'unsafe-inline';">
636	  <title>SprintHub</title>
637	  <link rel="stylesheet" href="${stylesUri}">
638	</head>
639	<body>
640	  <div id="root"></div>
641	  <script nonce="${nonce}" src="${scriptUri}"></script>
642	</body>
643	</html>`;
644	  }
645	
646	  public dispose() {
647	    SprintHubPanel.currentPanel = undefined;
648	    if (this._refreshTimer) {
649	      clearInterval(this._refreshTimer);
650	    }
651	    this._statusBarItem.hide();
652	    this._panel.dispose();
653	    while (this._disposables.length) {
654	      const d = this._disposables.pop();
655	      if (d) d.dispose();
656	    }
657	  }
658	}
