768	export async function generateStandupData(viewerLogin: string): Promise<{ data: StandupData; markdown: string }> {
769	  const token = await getToken();
770	  const yesterday = new Date(Date.now() - 24 * 60 * 60 * 1000).toISOString().split('T')[0];
771	  const today = new Date().toLocaleDateString('en-US', { year: 'numeric', month: 'long', day: 'numeric' });
772	
773	  const repoFromUrl = (url: string) => url.replace('https://api.github.com/repos/', '');
774	
775	  async function search(q: string): Promise<RawSearchIssue[]> {
776	    const resp = await fetch(`https://api.github.com/search/issues?q=${encodeURIComponent(q)}&per_page=30`, {
777	      headers: { Authorization: `bearer ${token}`, Accept: 'application/vnd.github+json' },
778	    });
779	    if (!resp.ok) return [];
780	    const json = (await resp.json()) as { items: RawSearchIssue[] };
781	    return json.items ?? [];
782	  }
783	
784	  const [mergedPRs, openPRs, commentedItems] = await Promise.all([
785	    search(`is:pr is:merged author:${viewerLogin} merged:>${yesterday}`),
786	    search(`is:pr is:open author:${viewerLogin}`),
787	    search(`commenter:${viewerLogin} updated:>${yesterday}`),
788	  ]);
789	
790	  // Remove items already listed in merged/open from the commented section
791	  const listedUrls = new Set([...mergedPRs, ...openPRs].map((i) => i.html_url));
792	  const uniqueCommented = commentedItems.filter((i) => !listedUrls.has(i.html_url));
793	
794	  function toRepoGroups(items: RawSearchIssue[]): StandupRepoGroup[] {
795	    const map = new Map<string, StandupRepoGroup['items']>();
796	    for (const item of items) {
797	      const repo = repoFromUrl(item.repository_url);
798	      if (!map.has(repo)) map.set(repo, []);
799	      map.get(repo)!.push({ number: item.number, title: item.title, url: item.html_url, isPR: !!item.pull_request });
800	    }
801	    return Array.from(map.entries()).map(([repo, its]) => ({ repo, items: its }));
802	  }
803	
804	  const rawSections: Array<{ key: string; icon: string; title: string; items: RawSearchIssue[] }> = [
805	    { key: 'merged',    icon: '✅', title: 'Merged PRs',    items: mergedPRs },
806	    { key: 'open',      icon: '🔄', title: 'Open PRs',      items: openPRs },
807	    { key: 'commented', icon: '💬', title: 'Commented on',  items: uniqueCommented },
808	  ];
809	
810	  const sections: StandupSection[] = rawSections
811	    .filter((s) => s.items.length > 0)
812	    .map((s) => ({ key: s.key, icon: s.icon, title: s.title, groups: toRepoGroups(s.items) }));
813	
814	  const data: StandupData = { date: today, sections };
815	
816	  // Generate markdown from structured data (used for the copy-as-markdown button)
817	  const lines: string[] = [`## Daily Standup — ${today}`, ''];
818	  if (sections.length === 0) {
819	    lines.push('*No activity found in the last 24 hours.*', '');
820	  } else {
821	    for (const section of sections) {
822	      lines.push(`### ${section.icon} ${section.title}`);
823	      for (const group of section.groups) {
824	        lines.push(`**${group.repo}**`);
825	        for (const item of group.items) {
826	          lines.push(`- [#${item.number} ${item.title}](${item.url})`);
827	        }
828	      }
829	      lines.push('');
830	    }
831	  }
832	  lines.push('*Generated by SprintHub*');
833	
834	  return { data, markdown: lines.join('\n') };
835	}
