1	import React, { useState, useEffect, useRef } from 'react';
2	import { BoardItem, CIState, CheckRun, GHLabel, LinkedPR, PRFile, ReviewInfo } from '../../src/types';
3	
4	// ─── Codeowners helper ────────────────────────────────────────────────────────
5	
6	function matchesCodeownersPattern(filename: string, pattern: string): boolean {
7	  const p = pattern.startsWith('/') ? pattern.slice(1) : pattern;
8	  if (p.endsWith('/')) return filename.startsWith(p);
9	  if (p.startsWith('*.')) return filename.endsWith(p.slice(1));
10	  if (p.includes('*')) {
11	    const re = new RegExp('^' + p.replace(/\./g, '\\.').replace(/\*/g, '[^/]*') + '$');
12	    return re.test(filename) || re.test(filename.split('/').pop() ?? '');
13	  }
14	  return filename === p || filename.startsWith(p + '/');
15	}
16	
17	export function resolveCodeowners(
18	  filename: string,
19	  entries: Array<{ pattern: string; owners: string[] }>
20	): string[] {
21	  let matched: string[] = [];
22	  for (const entry of entries) {
23	    if (matchesCodeownersPattern(filename, entry.pattern)) {
24	      matched = entry.owners;
25	    }
26	  }
27	  return matched;
28	}
29	
30	// ─── PR quality score ─────────────────────────────────────────────────────────
31	
32	interface QualityFlag {
33	  label: string;
34	  color: string;
35	}
36	
37	function computeQualityFlags(item: BoardItem, files: PRFile[] | null): QualityFlag[] {
38	  const flags: QualityFlag[] = [];
39	  const daysOpen = (Date.now() - new Date(item.createdAt).getTime()) / 86_400_000;
40	  const totalLines = (item.additions ?? 0) + (item.deletions ?? 0);
41	
42	  if (daysOpen > 7) flags.push({ label: `Stale · ${Math.floor(daysOpen)}d open`, color: '#f9e2af' });
43	  if (totalLines > 500) flags.push({ label: `Large · ${totalLines} lines`, color: '#f38ba8' });
44	  if (!item.body?.trim()) flags.push({ label: 'No description', color: '#fab387' });
45	  if (!item.reviewRequests?.length && !item.reviews?.length) {
46	    flags.push({ label: 'No reviewers', color: '#fab387' });
47	  }
48	  if (files && files.length > 0 && !files.some((f) => /test|spec/i.test(f.filename))) {
49	    flags.push({ label: 'No tests changed', color: '#a6adc8' });
50	  }
51	  return flags;
52	}
53	
54	// ─── Small utilities ──────────────────────────────────────────────────────────
55	
56	function timeAgo(iso: string): string {
57	  const diff = Date.now() - new Date(iso).getTime();
58	  const mins = Math.floor(diff / 60000);
59	  if (mins < 2) return 'just now';
60	  if (mins < 60) return `${mins}m ago`;
61	  const hours = Math.floor(mins / 60);
62	  if (hours < 24) return `${hours}h ago`;
63	  const days = Math.floor(hours / 24);
64	  if (days < 30) return `${days}d ago`;
65	  return new Date(iso).toLocaleDateString();
66	}
67	
68	function ciColor(conclusion: string | null, status: string): string {
69	  if (status === 'IN_PROGRESS' || status === 'QUEUED') return '#f9e2af';
70	  if (conclusion === 'SUCCESS') return '#a6e3a1';
71	  if (conclusion === 'FAILURE' || conclusion === 'TIMED_OUT') return '#f38ba8';
72	  if (conclusion === 'CANCELLED') return '#6c7086';
73	  return '#585b70';
74	}
75	
76	function ciLabel(conclusion: string | null, status: string): string {
77	  if (status === 'IN_PROGRESS') return 'running';
78	  if (['QUEUED', 'REQUESTED', 'WAITING', 'PENDING'].includes(status)) return 'queued';
79	  if (conclusion === 'SUCCESS') return 'pass';
80	  if (conclusion === 'FAILURE') return 'fail';
81	  if (conclusion === 'TIMED_OUT') return 'timeout';
