92	          <span>{parseInlineMarkdown(line.slice(2), onOpenUrl, `${i}`)}</span>
93	        </div>
94	      );
95	    } else if (line.trim() === '') {
96	      els.push(<div key={i} className="standup-spacer" />);
97	    } else {
98	      els.push(<p key={i} className="standup-p">{parseInlineMarkdown(line, onOpenUrl, `${i}`)}</p>);
99	    }
100	  }
101	  return <div className="standup-rendered">{els}</div>;
102	}
