106	function useDebounce<T>(value: T, delay: number): T {
107	  const [debounced, setDebounced] = useState(value);
108	  useEffect(() => {
109	    const id = setTimeout(() => setDebounced(value), delay);
110	    return () => clearTimeout(id);
111	  }, [value, delay]);
112	  return debounced;
113	}
