261	        <span className="lp-col-diff">Diff</span>
262	        <span className="lp-col-author">Author</span>
263	        <span className="lp-col-collabs">Collaborators</span>
264	        <span className="lp-col-branch">Repo / Branch</span>
265	      </div>
266	
267	      {!prs.length ? (
268	        <div className="lp-empty" style={{ marginTop: 40 }}>
269	          <svg width="28" height="28" viewBox="0 0 24 24" fill="none" stroke="#45475a" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round">
270	            <circle cx="18" cy="18" r="3"/><circle cx="6" cy="6" r="3"/>
