      const updated = col.find((i) => i.id === prev.id);
      if (updated) {
        // updatedAt changed → drop stale body so the useEffect below re-fetches
        return updated.updatedAt !== prev.updatedAt
          ? { ...updated }
          : { ...updated, body: prev.body };
