  -webkit-backdrop-filter: blur(80px) saturate(260%) brightness(1.04) !important;
  border: 1.5px solid transparent !important;
  background:
    linear-gradient(160deg, rgba(16,16,36,0.74) 0%, rgba(10,10,28,0.70) 100%) padding-box,
    linear-gradient(148deg,
      rgba(255,255,255,0.58) 0%,
      rgba(255,255,255,0.14) 35%,
      rgba(137,180,250,0.08) 65%,
      rgba(0,0,0,0.30) 100%) border-box !important;
  box-shadow:
    0 48px 120px rgba(0,0,0,0.72),
    0 0 0 0.5px rgba(255,255,255,0.05),
    inset 0 2px 0 rgba(255,255,255,0.30),
    inset 0 0 60px rgba(137,180,250,0.04) !important;
}
/* Top-left specular sheen */
.liquid-glass .standup-modal::before {
  content: '';
  position: absolute;
  top: 0; left: 0; right: 0;
  height: 58%;
  background: linear-gradient(
    155deg,
    rgba(255,255,255,0.16) 0%,
    rgba(255,255,255,0.05) 38%,
    transparent 100%
  );
  pointer-events: none;
  z-index: 0;
}
/* Bottom ambient light bloom */
.liquid-glass .standup-modal::after {
  content: '';
  position: absolute;
  bottom: 0; left: 0; right: 0;
  height: 42%;
  background: radial-gradient(
    ellipse 70% 60% at 50% 100%,
    rgba(137,180,250,0.08) 0%,
    transparent 100%
  );
  pointer-events: none;
  z-index: 0;
}
.liquid-glass .standup-modal > * { position: relative; z-index: 1; }
/* Glass-style internal dividers */
.liquid-glass .standup-header { border-bottom-color: rgba(255,255,255,0.07) !important; background: rgba(255,255,255,0.02) !important; }
.liquid-glass .standup-footer { border-top-color: rgba(255,255,255,0.06) !important; }

