      rgba(0,0,0,0.32) 100%) border-box !important;
  box-shadow:
    0 48px 120px rgba(0,0,0,0.72),
    0 0 0 0.5px rgba(255,255,255,0.05),
    /* top-edge specular rim */
    inset 0 2px 0 rgba(255,255,255,0.30),
    /* chromatic inner glows: blue top-left, violet bottom-right */
    inset 6px 6px 40px rgba(100,160,255,0.06),
    inset -6px -6px 40px rgba(203,166,247,0.05) !important;
}
/* Animated top-left specular sheen */
.liquid-glass .standup-modal::before {
  content: '';
  position: absolute;
  top: 0; left: 0; right: 0;
  height: 60%;
  background: linear-gradient(
    155deg,
    rgba(255,255,255,0.18) 0%,
    rgba(255,255,255,0.05) 40%,
    transparent 100%
  );
  animation: glassSheen 5s ease-in-out infinite;
  pointer-events: none;
  z-index: 0;
}
/* Chromatic dispersion: blue at top-left corner, violet at bottom-right, ambient bloom at bottom */
.liquid-glass .standup-modal::after {
  content: '';
  position: absolute;
  inset: 0;
  background:
