}

.spinner {
  width: 28px;
  height: 28px;
  border: 3px solid #2a2a3d;
  border-top-color: #89b4fa;
  border-radius: 50%;
  animation: spin 0.75s linear infinite;
}

.state-title { color: #a6adc8; font-size: 14px; font-weight: 600; }
