/* Glass skeleton — Ein UI glass-skeleton pattern */
.skeleton-board {
  display: flex;
  flex-direction: column;
  gap: 10px;
  padding: 12px 16px;
  flex: 1;
}
.skeleton-group {
  border: 1px solid rgba(255,255,255,0.06);
  border-radius: 10px;
  overflow: hidden;
}
.skeleton-col-header {
  height: 34px;
  background: rgba(255,255,255,0.03);
  border-bottom: 1px solid rgba(255,255,255,0.05);
}
.skeleton-row {
  display: grid;
  grid-template-columns: 34px 36px 1fr 80px 28px 28px;
  gap: 10px;
  align-items: center;
  padding: 9px 12px;
  border-bottom: 1px solid rgba(255,255,255,0.03);
}
.skeleton-row:last-child { border-bottom: none; }
.skeleton-pulse {
  position: relative;
  overflow: hidden;
  border-radius: 4px;
  background: rgba(255,255,255,0.05);
}
.skeleton-pulse::before {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(90deg, transparent 0%, rgba(255,255,255,0.08) 50%, transparent 100%);
  background-size: 400% 100%;
  animation: shimmer 2s linear infinite;
}
.sk-age   { height: 11px; }
.sk-dots  { height: 11px; }
.sk-title { height: 11px; }
.sk-diff  { height: 11px; border-radius: 4px; }
.sk-avatar { height: 22px; border-radius: 50%; }
.sk-avatar2 { height: 22px; border-radius: 50%; }

