195	  // Tracks the last fetchBody key sent to avoid duplicate requests when
196	  // handleSelectItem and the stale-body useEffect both fire for the same item.
197	  const lastBodyFetchKey = React.useRef<string | null>(null);
198	
199	  // Keyboard navigation
200	  const searchInputRef = useRef<HTMLInputElement>(null);
201	  const keyboardFocusedIndex = useRef<number>(-1);
202	
203	  useEffect(() => {
204	    const handler = (event: MessageEvent) => {
205	      const msg = event.data as ExtensionMessage;
206	      switch (msg.type) {
207	        case 'loading':
208	          setIsLoadingMore(true);
209	          if (state !== 'data') setState('loading');
210	          break;
211	        case 'refreshing':
212	          setIsLoadingMore(true);
213	          break;
214	        case 'dataComplete':
215	          setIsLoadingMore(false);
216	          setIsRefreshing(false);
217	          // Auto-select deferred here so the full sprint list (all pages) is known.
218	          if (sprintNeedsAutoSelect.current && dataRef.current?.sprints.length) {
219	            sprintNeedsAutoSelect.current = false;
220	            const { sprints } = dataRef.current;
221	            setSprintFilter((prev) => {
222	              if (prev !== null) return sprints.includes(prev) ? prev : (sprints[0] ?? null);
223	              return sprints[0] ?? null;
224	            });
225	          }
226	          break;
227	        case 'data': {
228	          dataRef.current = msg.payload;
229	          setData(msg.payload);
230	          setState('data');
231	          // Only validate an existing selection against the incoming sprint list.
232	          // Initial auto-select is deferred to dataComplete (full dataset).
233	          setSprintFilter((prev) => {
234	            const { sprints } = msg.payload;
235	            if (prev === null) return null; // keep null until dataComplete auto-selects
236	            if (sprints.length === 0) return null;
237	            return sprints.includes(prev) ? prev : sprints[0];
238	          });
239	          // Keep the open detail panel in sync with refreshed board data.
240	          // Scan groups with early exit instead of flattening to avoid
241	          // unnecessary allocations on large boards.
242	          setDetailItem((prev) => {
243	            if (!prev) return prev;
244	            for (const col of Object.values(msg.payload.groups)) {
245	              const updated = col.find((i) => i.id === prev.id);
246	              if (updated) {
247	                // updatedAt changed → drop stale body so the useEffect below re-fetches
248	                return updated.updatedAt !== prev.updatedAt
249	                  ? { ...updated }
250	                  : { ...updated, body: prev.body };
251	              }
252	            }
253	            const linkedPR = (msg.payload.linkedIssuePRs ?? []).find((i) => i.id === prev.id);
254	            if (linkedPR) return { ...linkedPR, body: prev.body };
255	            // Item absent from the full payload — closed/merged/removed; close the panel
256	            return null;
257	          });
258	          break;
259	        }
260	        case 'error':
261	          setErrorMsg(msg.message);
262	          setState('error');
