230	    }
231	    const intervalMinutes =
232	      vscode.workspace.getConfiguration('sprinthub').get<number>('refreshInterval', 5);
233	    if (intervalMinutes > 0) {
234	      this._refreshTimer = setInterval(
235	        () => this._loadData(),
236	        intervalMinutes * 60 * 1000
237	      );
238	    }
239	  }
240	
241	  private async _loadData() {
242	    const config = vscode.workspace.getConfiguration('sprinthub');
243	    const owner = config.get<string>('owner', '').trim();
244	    const projectNumber = config.get<number>('projectNumber', 0);
245	    const ownerType = config.get<string>('ownerType', 'organization');
246	    const statusFieldName = config.get<string>('statusFieldName', 'Status');
247	
248	    if (!owner || !projectNumber) {
249	      this._post({
250	        type: 'error',
251	        message:
252	          'Please set sprinthub.owner and sprinthub.projectNumber in your VS Code settings (File → Preferences → Settings → search "SprintHub").',
253	      });
254	      return;
255	    }
256	
257	    // Show cached data immediately so the board is visible while fresh data loads.
258	    // Cache is scoped to the current config so switching projects never shows stale data.
259	    const cacheKey = SprintHubPanel._cacheKey(owner, projectNumber, ownerType, statusFieldName);
260	    const cached = this._context.globalState.get<RunwayData>(cacheKey);
261	    if (cached) {
262	      this._post({ type: 'data', payload: cached });
263	      this._updateStatusBar(cached); // fix: status bar available immediately from cache
264	      this._post({ type: 'refreshing' });
265	    } else {
266	      this._post({ type: 'loading' });
267	    }
268	
269	    try {
270	      const data = await fetchProjectData(
271	        owner,
272	        projectNumber,
273	        ownerType === 'organization',
274	        statusFieldName,
275	        (partial) => {
276	          // Deliver each page to the webview as it arrives
277	          this._post({ type: 'data', payload: partial });
278	          this._updateStatusBar(partial);
279	        }
280	      );
281	      this._lastData = data;
282	      // Persist for next open — attach .catch() so a storage rejection doesn't go silent
283	      this._context.globalState.update(cacheKey, data).then(undefined, (err: unknown) => {
284	        console.error('SprintHub: cache write failed', err);
285	      });
286	      // Fetch linked PRs first, then run conflict check with the enriched dataset.
287	      // Running conflicts on data.linkedIssuePRs=[] would miss linked-PR conflicts.
288	      void (async () => {
289	        try {
290	          const linkedPRs = await this._fetchLinkedPRsBackground(data.groups);
291	          await this._checkConflicts({ ...data, linkedIssuePRs: linkedPRs });
292	        } finally {
293	          this._post({ type: 'dataComplete' });
294	        }
295	      })();
296	    } catch (err: unknown) {
297	      const msg = err instanceof Error ? err.message : String(err);
298	      this._post({ type: 'error', message: msg });
299	      this._post({ type: 'dataComplete' });
300	    }
301	  }
302	
303	  // ─── Phase 1: Work-On-This Engine ──────────────────────────────────────────
304	
305	  private async _workOnThis(branchName: string, _owner: string, _repo: string) {
306	    const cwd = vscode.workspace.workspaceFolders?.[0]?.uri.fsPath;
307	    if (!cwd) {
308	      vscode.window.showErrorMessage('SprintHub: No workspace folder open to checkout branch.');
309	      return;
310	    }
311	
312	    let branchExists = false;
313	    try {
314	      await exec(`git rev-parse --verify "${branchName}"`, { cwd });
315	      branchExists = true;
316	    } catch {
317	      branchExists = false;
318	    }
319	
320	    let terminal = vscode.window.terminals.find((t) => t.name === 'SprintHub');
321	    if (!terminal) {
322	      terminal = vscode.window.createTerminal('SprintHub');
323	    }
324	    terminal.show(true);
325	
326	    if (branchExists) {
327	      terminal.sendText(`git checkout ${branchName}`);
328	    } else {
329	      terminal.sendText(`git fetch origin ${branchName} 2>/dev/null; git checkout -b ${branchName} origin/${branchName} 2>/dev/null || git checkout ${branchName}`);
330	    }
331	
332	    // Focus the most recently modified file in the workspace
333	    setTimeout(() => void this._focusMostRecentFile(cwd), 2000);
334	  }
335	
336	  private async _focusMostRecentFile(cwd: string) {
337	    try {
338	      const { stdout } = await exec('git diff --name-only HEAD', { cwd });
339	      const files = stdout.trim().split('\n').filter(Boolean);
340	      if (!files.length) return;
341	      const found = await vscode.workspace.findFiles(files[0], '**/node_modules/**', 1);
342	      if (found.length) {
343	        const doc = await vscode.workspace.openTextDocument(found[0]);
344	        await vscode.window.showTextDocument(doc, { preserveFocus: false });
345	      }
346	    } catch {
347	      // silently skip if git diff fails (detached HEAD, etc.)
348	    }
349	  }
350	
351	  // ─── Phase 1: File-Level Deep Linking ──────────────────────────────────────
352	
353	  private async _fetchPRFiles(prKey: string, owner: string, repo: string, prNumber: number) {
354	    try {
355	      const files = await fetchPRFiles(owner, repo, prNumber);
356	      this._post({ type: 'prFiles', prKey, files });
357	    } catch {
358	      this._post({ type: 'prFiles', prKey, files: [] });
359	    }
360	  }
361	
362	  private async _openPRFile(owner: string, repo: string, _prNumber: number, filename: string, patch?: string) {
363	    const cwd = vscode.workspace.workspaceFolders?.[0]?.uri.fsPath;
364	    if (!cwd) {
365	      vscode.window.showWarningMessage('SprintHub: No workspace folder open.');
366	      return;
367	    }
368	
369	    const found = await vscode.workspace.findFiles(filename, '**/node_modules/**', 1);
370	    if (!found.length) {
371	      vscode.window.showWarningMessage(`SprintHub: File not found locally: ${filename}`);
372	      return;
373	    }
374	
375	    const doc = await vscode.workspace.openTextDocument(found[0]);
376	    let line = 0;
377	    if (patch) {
378	      const match = patch.match(/@@ -\d+(?:,\d+)? \+(\d+)/);
379	      if (match) line = Math.max(0, parseInt(match[1], 10) - 1);
380	    }
381	    const selection = new vscode.Range(line, 0, line, 0);
382	    await vscode.window.showTextDocument(doc, { selection });
383	  }
384	
385	  // ─── Linked PRs background fetch ───────────────────────────────────────────
386	
387	  private async _fetchLinkedPRsBackground(groups: RunwayData['groups']): Promise<BoardItem[]> {
388	    try {
389	      const prs = await fetchLinkedPRsForBoard(groups);
390	      this._post({ type: 'linkedIssuePRs', prs });
391	      return prs;
392	    } catch {
393	      return []; // best-effort — Dashboard shows no linked PRs, conflict check still runs
394	    }
395	  }
396	
397	  // ─── Phase 2: Hotspot Conflict Monitor ─────────────────────────────────────
398	
399	  private async _checkConflicts(data: RunwayData) {
400	    const cwd = vscode.workspace.workspaceFolders?.[0]?.uri.fsPath;
401	    if (!cwd) return;
402	
403	    let localDirty: Set<string>;
404	    try {
405	      const { stdout } = await exec('git diff --name-only HEAD', { cwd });
406	      localDirty = new Set(stdout.trim().split('\n').filter(Boolean));
407	    } catch {
408	      return;
409	    }
410	
411	    if (!localDirty.size) {
412	      this._post({ type: 'conflictThreats', threats: [] });
413	      return;
414	    }
415	
416	    // Collect open PRs from board + linked PRs
417	    const openPRs: Array<{ owner: string; repo: string; number: number; title: string; author: string; url: string }> = [];
418	    const allBoardItems: BoardItem[] = [...Object.values(data.groups).flat(), ...(data.linkedIssuePRs ?? [])];
419	    for (const item of allBoardItems) {
420	      if (item.type === 'PULL_REQUEST' && item.state === 'OPEN' && item.repositoryOwner && item.repository) {
421	        openPRs.push({
422	          owner: item.repositoryOwner,
423	          repo: item.repository,
424	          number: item.number,
425	          title: item.title,
426	          author: item.author.login,
427	          url: item.url,
428	        });
429	      }
430	    }
431	
432	    if (!openPRs.length) {
433	      this._post({ type: 'conflictThreats', threats: [] });
434	      return;
435	    }
436	
437	    try {
438	      const prFilesMap = await fetchAllOpenPRFiles(openPRs.map((p) => ({ owner: p.owner, repo: p.repo, number: p.number })));
439	      const threats: ConflictThreat[] = [];
440	
441	      for (const pr of openPRs) {
442	        const key = `${pr.owner}/${pr.repo}#${pr.number}`;
443	        const files = prFilesMap.get(key) ?? [];
444	        for (const file of files) {
445	          if (localDirty.has(file.filename)) {
446	            threats.push({
447	              filename: file.filename,
448	              prNumber: pr.number,
449	              prTitle: pr.title,
450	              prAuthor: pr.author,
451	              prUrl: pr.url,
452	            });
453	          }
454	        }
455	      }
456	
457	      this._post({ type: 'conflictThreats', threats });
458	    } catch {
459	      // conflict check is best-effort
460	    }
461	  }
462	
463	  // ─── Phase 2: Status Bar Blocker Watchdog ──────────────────────────────────
464	
465	  private _updateStatusBar(data: RunwayData) {
466	    const allItems: BoardItem[] = [...Object.values(data.groups).flat(), ...(data.linkedIssuePRs ?? [])];
467	    const openPRs = allItems.filter((i) => i.type === 'PULL_REQUEST' && i.state === 'OPEN');
468	
469	    const ciFailures = openPRs.filter((i) => i.ciState === 'FAILURE' || i.ciState === 'ERROR');
470	    const changesRequested = openPRs.filter((i) =>
471	      i.reviews?.some((r) => r.state === 'CHANGES_REQUESTED')
472	    );
473	
474	    const total = ciFailures.length + changesRequested.length;
475	
476	    if (total === 0) {
477	      this._statusBarItem.text = '$(check) SprintHub';
478	      this._statusBarItem.backgroundColor = undefined;
479	    } else {
480	      const parts: string[] = [];
481	      if (ciFailures.length) parts.push(`${ciFailures.length} CI fail${ciFailures.length > 1 ? 's' : ''}`);
482	      if (changesRequested.length) parts.push(`${changesRequested.length} changes req`);
483	      this._statusBarItem.text = `$(warning) ${parts.join(' · ')}`;
484	      this._statusBarItem.backgroundColor = new vscode.ThemeColor('statusBarItem.warningBackground');
485	    }
486	
487	    this._statusBarItem.show();
488	
489	    // Store for use in showBlockers quick-pick
490	    (this as unknown as Record<string, unknown>)._blockerPRs = { ciFailures, changesRequested };
491	  }
492	
493	  public showBlockersQuickPick() {
494	    const stored = (this as unknown as Record<string, unknown>)._blockerPRs as
495	      | { ciFailures: BoardItem[]; changesRequested: BoardItem[] }
496	      | undefined;
497	    if (!stored) {
498	      vscode.window.showInformationMessage('SprintHub: No blocker data loaded yet.');
499	      return;
500	    }
501	
502	    const { ciFailures, changesRequested } = stored;
503	    const items: vscode.QuickPickItem[] = [];
504	
505	    if (ciFailures.length) {
506	      items.push({ label: '$(error) CI Failing', kind: vscode.QuickPickItemKind.Separator });
507	      for (const pr of ciFailures) {
508	        items.push({ label: `#${pr.number} ${pr.title}`, description: `${pr.repositoryOwner}/${pr.repository}`, detail: pr.url });
509	      }
510	    }
511	
512	    if (changesRequested.length) {
513	      items.push({ label: '$(git-pull-request) Changes Requested', kind: vscode.QuickPickItemKind.Separator });
514	      for (const pr of changesRequested) {
515	        items.push({ label: `#${pr.number} ${pr.title}`, description: `${pr.repositoryOwner}/${pr.repository}`, detail: pr.url });
516	      }
517	    }
518	
519	    if (!items.length) {
520	      vscode.window.showInformationMessage('SprintHub: All PRs are healthy!');
521	      return;
522	    }
523	
524	    void vscode.window.showQuickPick(items, { title: 'SprintHub Blockers', placeHolder: 'Select a PR to open on GitHub' }).then((selected) => {
525	      if (selected?.detail) {
526	        void vscode.env.openExternal(vscode.Uri.parse(selected.detail));
527	      }
528	    });
529	  }
530	
531	  // ─── Phase 3: Standup Markdown Generator ───────────────────────────────────
532	
533	  private async _generateStandup(viewerLogin: string) {
534	    try {
535	      const { data, markdown } = await generateStandupData(viewerLogin);
536	      this._post({ type: 'standup', data, markdown });
537	    } catch (err) {
538	      const msg = err instanceof Error ? err.message : String(err);
539	      this._post({ type: 'standup', data: { date: '', sections: [], error: msg }, markdown: `*Error generating standup: ${msg}*` });
540	    }
541	  }
542	
543	  // ─── Phase 3: Metadata Sync ─────────────────────────────────────────────────
544	
545	  private async _updateMetadata(
546	    itemId: string,
547	    owner: string,
548	    repo: string,
549	    issueNumber: number,
550	    labels?: string[],
551	    assignees?: string[]
552	  ) {
553	    try {
554	      const updated = await updateIssueMetadata(owner, repo, issueNumber, labels, assignees);
555	      this._post({ type: 'metadataUpdated', itemId, labels: updated.labels, assignees: updated.assignees });
556	    } catch (err) {
557	      const msg = err instanceof Error ? err.message : String(err);
558	      vscode.window.showErrorMessage(`SprintHub: Failed to update metadata — ${msg}`);
559	    }
560	  }
561	
562	  private async _fetchRepoLabels(owner: string, repo: string) {
563	    try {
564	      const labels = await fetchRepoLabels(owner, repo);
565	      this._post({ type: 'repoLabels', owner, repo, labels });
566	    } catch {
567	      this._post({ type: 'repoLabels', owner, repo, labels: [] });
568	    }
569	  }
570	
571	  // ─── v2 extras ───────────────────────────────────────────────────────────────
572	
573	  private async _convertDraftToReady(itemId: string, owner: string, repo: string, prNumber: number) {
574	    try {
575	      await convertDraftToReady(owner, repo, prNumber);
576	      this._post({ type: 'prReadied', itemId });
577	    } catch (err) {
578	      vscode.window.showErrorMessage(`SprintHub: ${err instanceof Error ? err.message : String(err)}`);
579	    }
580	  }
581	
582	  private async _mergePR(
583	    itemId: string,
584	    owner: string,
585	    repo: string,
586	    prNumber: number,
587	    mergeMethod: 'merge' | 'squash' | 'rebase'
588	  ) {
589	    try {
590	      await mergePR(owner, repo, prNumber, mergeMethod);
591	      this._post({ type: 'prMerged', itemId });
592	      vscode.window.showInformationMessage(`SprintHub: PR #${prNumber} merged successfully.`);
593	    } catch (err) {
594	      vscode.window.showErrorMessage(`SprintHub: ${err instanceof Error ? err.message : String(err)}`);
595	    }
596	  }
597	
598	  private async _fetchCodeowners(owner: string, repo: string) {
599	    try {
600	      const entries = await fetchCodeowners(owner, repo);
601	      this._post({ type: 'codeowners', owner, repo, entries });
602	    } catch {
603	      this._post({ type: 'codeowners', owner, repo, entries: [] });
604	    }
605	  }
606	
607	  private async _fetchSettingsOwners() {
608	    try {
609	      const owners = await fetchSettingsOwners();
610	      this._post({ type: 'settingsOwners', owners });
611	    } catch {
612	      this._post({ type: 'settingsOwners', owners: [] });
613	    }
614	  }
615	
616	  private async _fetchSettingsProjects(owner: string, ownerType: 'organization' | 'user') {
617	    try {
618	      const projects = await fetchSettingsProjects(owner, ownerType);
619	      this._post({ type: 'settingsProjects', projects });
620	    } catch {
621	      this._post({ type: 'settingsProjects', projects: [] });
622	    }
623	  }
624	
625	  // ───────────────────────────────────────────────────────────────────────────
626	
627	  private _post(message: ExtensionMessage) {
628	    this._panel.webview.postMessage(message);
629	  }
630	
631	  private _buildHtml(webview: vscode.Webview): string {
632	    const scriptUri = webview.asWebviewUri(
633	      vscode.Uri.joinPath(this._extensionUri, 'out', 'webview.js')
634	    );
635	    const stylesUri = webview.asWebviewUri(
636	      vscode.Uri.joinPath(this._extensionUri, 'out', 'styles.css')
637	    );
638	    const nonce = getNonce();
639	
640	    return /* html */ `<!DOCTYPE html>
641	<html lang="en">
642	<head>
643	  <meta charset="UTF-8">
644	  <meta name="viewport" content="width=device-width, initial-scale=1.0">
645	  <meta http-equiv="Content-Security-Policy"
646	    content="default-src 'none';
647	             img-src ${webview.cspSource} https: data:;
648	             script-src 'nonce-${nonce}';
649	             style-src ${webview.cspSource} 'unsafe-inline';">
650	  <title>SprintHub</title>
651	  <link rel="stylesheet" href="${stylesUri}">
652	</head>
653	<body>
654	  <div id="root"></div>
655	  <script nonce="${nonce}" src="${scriptUri}"></script>
656	</body>
657	</html>`;
658	  }
659	
660	  public dispose() {
661	    SprintHubPanel.currentPanel = undefined;
662	    if (this._refreshTimer) {
663	      clearInterval(this._refreshTimer);
664	    }
665	    this._statusBarItem.hide();
666	    this._panel.dispose();
667	    while (this._disposables.length) {
668	      const d = this._disposables.pop();
669	      if (d) d.dispose();
670	    }
671	  }
672	}
