2	import { BoardItem, CIState, ReviewInfo } from '../../src/types';
3	import { STALE_THRESHOLD_DAYS } from '../constants';
4	
5	interface Props {
6	  items: BoardItem[];
7	  linkedIssuePRs?: BoardItem[];
8	  viewerLogin: string;
9	  onSelect: (item: BoardItem) => void;
