11	}
12	
13	// ─── Group logic ────────────────────────────────────────────────────────────
14	
15	type LaunchpadGroup =
16	  | 'Ready to Merge'
17	  | 'Changes Requested'
18	  | 'CI Failing'
19	  | 'Ready for Review'
20	  | 'Needs Review'
21	  | 'In Progress'
22	  | 'Draft';
23	
24	const GROUP_ORDER: LaunchpadGroup[] = [
25	  'Ready to Merge',
26	  'Changes Requested',
27	  'CI Failing',
28	  'Ready for Review',
29	  'Needs Review',
30	  'In Progress',
31	  'Draft',
32	];
33	
34	const GROUP_META: Record<LaunchpadGroup, { color: string; icon: string; desc: string }> = {
35	  'Ready to Merge':    { color: '#a6e3a1', icon: '🚀', desc: 'Approved and all checks passed' },
36	  'Changes Requested': { color: '#f38ba8', icon: '✗',  desc: 'Review requested changes' },
37	  'CI Failing':        { color: '#f38ba8', icon: '✕',  desc: 'Checks are failing' },
38	  'Ready for Review':  { color: '#f9e2af', icon: '👁',  desc: 'In the Ready for Review column — awaiting review' },
39	  'Needs Review':      { color: '#cba6f7', icon: '❓',  desc: 'No reviewer assigned yet' },
40	  'In Progress':       { color: '#89b4fa', icon: '◑',  desc: 'Work in progress' },
41	  'Draft':             { color: '#585b70', icon: '✎',  desc: 'Draft pull requests' },
42	};
43	
44	function getPRGroup(item: BoardItem): LaunchpadGroup {
45	  if (item.isDraft) return 'Draft';
46	
47	  const hasChangesRequested = item.reviews?.some((r) => r.state === 'CHANGES_REQUESTED');
48	  if (hasChangesRequested) return 'Changes Requested';
49	
50	  if (item.ciState === 'FAILURE' || item.ciState === 'ERROR') return 'CI Failing';
51	
52	  const isApproved = item.reviews?.some((r) => r.state === 'APPROVED');
53	  const ciOk = !item.ciState || item.ciState === 'SUCCESS' || item.ciState === 'none' || item.ciState === 'EXPECTED';
54	  if (isApproved && ciOk) return 'Ready to Merge';
55	
56	  // Board column "Ready for review" (case-insensitive) takes priority over generic grouping
