.lp-wrap {
  padding: 8px 12px 16px;
  overflow-x: auto;
  min-width: 0;
}

.lp-toolbar {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 4px 0 10px;
  flex-wrap: wrap;
}

.lp-count {
  font-size: 11px;
  color: #6c7086;
  flex: 1;
}

.lp-filter-btn {
  display: flex;
  align-items: center;
  gap: 5px;
  padding: 4px 10px;
  border-radius: 6px;
  border: 1px solid #2a2a3d;
  background: transparent;
  color: #6c7086;
  font-size: 11px;
  font-weight: 500;
  cursor: pointer;
  transition: all 0.15s;
}
.lp-filter-btn:hover {
  background: #1e1e2d;
  color: #cdd6f4;
  border-color: #45475a;
}
.lp-filter-btn.active {
  background: rgba(137,180,250,0.15);
  color: #89b4fa;
  border-color: rgba(137,180,250,0.4);
}
.light-theme .lp-filter-btn {
  border-color: #bcc0cc;
  color: #6c6f85;
}
.light-theme .lp-filter-btn:hover {
  background: #ccd0da;
  color: #4c4f69;
}
.light-theme .lp-filter-btn.active {
  background: rgba(30,102,245,0.12);
  color: #1e66f5;
  border-color: rgba(30,102,245,0.4);
}
.light-theme .lp-count { color: #8c8fa1; }

.lp-header-row {
  display: grid;
  grid-template-columns: 36px 52px 1fr 80px 30px 80px 140px;
  gap: 4px;
  align-items: center;
  padding: 0 0 6px;
  border-bottom: 1px solid #2a2a3d;
  color: #45475a;
  font-size: 10px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

/* Clip header label text so it doesn't overflow into the next column */
.lp-col-age, .lp-col-status, .lp-col-title,
.lp-col-diff, .lp-col-author, .lp-col-collabs, .lp-col-branch {
  overflow: hidden;
  white-space: nowrap;
  text-overflow: clip;
  min-width: 0;
}
.lp-col-age { text-align: right; }

.lp-group {
  border: 1px solid #2a2a3d;
  border-radius: 10px;
  overflow: hidden;
  margin-bottom: 8px;
}

.lp-group-header {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 7px 12px;
  cursor: pointer;
  user-select: none;
  background: rgba(255,255,255,0.015);
  border-bottom: 1px solid #1e1e2e;
}

.lp-group-header:hover {
  background: rgba(255,255,255,0.03);
}

.lp-group-icon {
  font-size: 12px;
  width: 16px;
  text-align: center;
  flex-shrink: 0;
}

.lp-group-name {
  font-size: 12px;
  font-weight: 600;
  flex: 1;
}

.lp-group-rows {}

.lp-row {
  display: grid;
