220	      // null signals a transient failure — the webview will not cache it so the
221	      // next open will retry rather than permanently showing an empty body.
222	      this._post({ type: 'itemBody', itemId, body: null, updatedAt });
223	    }
224	  }
225	
226	  private _scheduleRefresh() {
227	    if (this._refreshTimer) {
228	      clearInterval(this._refreshTimer);
229	    }
230	    const intervalMinutes =
231	      vscode.workspace.getConfiguration('sprinthub').get<number>('refreshInterval', 5);
232	    if (intervalMinutes > 0) {
233	      this._refreshTimer = setInterval(
234	        () => this._loadData(),
235	        intervalMinutes * 60 * 1000
236	      );
237	    }
238	  }
239	
240	  private async _loadData() {
241	    const config = vscode.workspace.getConfiguration('sprinthub');
242	    const owner = config.get<string>('owner', '').trim();
243	    const projectNumber = config.get<number>('projectNumber', 0);
244	    const ownerType = config.get<string>('ownerType', 'organization');
245	    const statusFieldName = config.get<string>('statusFieldName', 'Status');
246	
247	    if (!owner || !projectNumber) {
248	      this._post({
249	        type: 'error',
250	        message:
251	          'Please set sprinthub.owner and sprinthub.projectNumber in your VS Code settings (File → Preferences → Settings → search "SprintHub").',
252	      });
253	      return;
254	    }
255	
256	    // Show cached data immediately so the board is visible while fresh data loads.
257	    // Cache is scoped to the current config so switching projects never shows stale data.
258	    const cacheKey = SprintHubPanel._cacheKey(owner, projectNumber, ownerType, statusFieldName);
259	    const cached = this._context.globalState.get<RunwayData>(cacheKey);
260	    if (cached) {
261	      this._post({ type: 'data', payload: cached });
262	      this._updateStatusBar(cached); // fix: status bar available immediately from cache
263	      this._post({ type: 'refreshing' });
264	    } else {
265	      this._post({ type: 'loading' });
266	    }
267	
268	    try {
269	      const isRefresh = !!cached;
270	      const data = await fetchProjectData(
271	        owner,
272	        projectNumber,
273	        ownerType === 'organization',
274	        statusFieldName,
275	        isRefresh ? undefined : (partial) => {
276	          this._post({ type: 'data', payload: partial });
277	          this._updateStatusBar(partial);
278	        }
279	      );
280	      if (isRefresh) {
281	        // Post the complete fresh data atomically — no partial updates during refresh
282	        this._post({ type: 'data', payload: data });
283	        this._updateStatusBar(data);
284	      }
285	      // Persist for next open — attach .catch() so a storage rejection doesn't go silent
286	      this._context.globalState.update(cacheKey, data).then(undefined, (err: unknown) => {
287	        console.error('SprintHub: cache write failed', err);
288	      });
289	      // Signal that the main board data is ready — the webview can render now.
290	      // Linked PRs and conflict checks run in the background and push updates
291	      // incrementally via linkedIssuePRs / conflictThreats messages.
292	      this._post({ type: 'dataComplete' });
293	      void (async () => {
294	        try {
295	          const linkedPRs = await this._fetchLinkedPRsBackground(data.groups);
296	          await this._checkConflicts({ ...data, linkedIssuePRs: linkedPRs });
297	        } catch {
298	          // best-effort — linked PRs and conflict checks are non-blocking
299	        }
300	      })();
301	    } catch (err: unknown) {
302	      const msg = err instanceof Error ? err.message : String(err);
303	      this._post({ type: 'error', message: msg });
304	      this._post({ type: 'dataComplete' });
305	    }
306	  }
307	
308	  // ─── Phase 1: Work-On-This Engine ──────────────────────────────────────────
309	
310	  private async _workOnThis(branchName: string, _owner: string, _repo: string) {
311	    const cwd = vscode.workspace.workspaceFolders?.[0]?.uri.fsPath;
312	    if (!cwd) {
313	      vscode.window.showErrorMessage('SprintHub: No workspace folder open to checkout branch.');
314	      return;
315	    }
316	
317	    let branchExists = false;
318	    try {
319	      await exec(`git rev-parse --verify "${branchName}"`, { cwd });
320	      branchExists = true;
321	    } catch {
322	      branchExists = false;
323	    }
324	
325	    let terminal = vscode.window.terminals.find((t) => t.name === 'SprintHub');
326	    if (!terminal) {
327	      terminal = vscode.window.createTerminal('SprintHub');
328	    }
329	    terminal.show(true);
330	
331	    if (branchExists) {
332	      terminal.sendText(`git checkout ${branchName}`);
333	    } else {
334	      terminal.sendText(`git fetch origin ${branchName} 2>/dev/null; git checkout -b ${branchName} origin/${branchName} 2>/dev/null || git checkout ${branchName}`);
335	    }
336	
337	    // Focus the most recently modified file in the workspace
338	    setTimeout(() => void this._focusMostRecentFile(cwd), 2000);
339	  }
340	
341	  private async _focusMostRecentFile(cwd: string) {
342	    try {
343	      const { stdout } = await exec('git diff --name-only HEAD', { cwd });
344	      const files = stdout.trim().split('\n').filter(Boolean);
345	      if (!files.length) return;
346	      const found = await vscode.workspace.findFiles(files[0], '**/node_modules/**', 1);
347	      if (found.length) {
348	        const doc = await vscode.workspace.openTextDocument(found[0]);
349	        await vscode.window.showTextDocument(doc, { preserveFocus: false });
350	      }
351	    } catch {
352	      // silently skip if git diff fails (detached HEAD, etc.)
353	    }
354	  }
355	
356	  // ─── Phase 1: File-Level Deep Linking ──────────────────────────────────────
357	
358	  private async _fetchPRFiles(prKey: string, owner: string, repo: string, prNumber: number) {
359	    try {
360	      const files = await fetchPRFiles(owner, repo, prNumber);
361	      this._post({ type: 'prFiles', prKey, files });
362	    } catch {
363	      this._post({ type: 'prFiles', prKey, files: [] });
364	    }
365	  }
366	
367	  private async _openPRFile(owner: string, repo: string, _prNumber: number, filename: string, patch?: string) {
368	    const cwd = vscode.workspace.workspaceFolders?.[0]?.uri.fsPath;
369	    if (!cwd) {
370	      vscode.window.showWarningMessage('SprintHub: No workspace folder open.');
371	      return;
372	    }
373	
374	    const found = await vscode.workspace.findFiles(filename, '**/node_modules/**', 1);
375	    if (!found.length) {
376	      vscode.window.showWarningMessage(`SprintHub: File not found locally: ${filename}`);
377	      return;
378	    }
379	
380	    const doc = await vscode.workspace.openTextDocument(found[0]);
381	    let line = 0;
382	    if (patch) {
383	      const match = patch.match(/@@ -\d+(?:,\d+)? \+(\d+)/);
384	      if (match) line = Math.max(0, parseInt(match[1], 10) - 1);
385	    }
386	    const selection = new vscode.Range(line, 0, line, 0);
387	    await vscode.window.showTextDocument(doc, { selection });
388	  }
389	
390	  // ─── Linked PRs background fetch ───────────────────────────────────────────
391	
392	  private async _fetchLinkedPRsBackground(groups: RunwayData['groups']): Promise<BoardItem[]> {
393	    try {
394	      const prs = await fetchLinkedPRsForBoard(groups);
395	      this._post({ type: 'linkedIssuePRs', prs });
396	      return prs;
397	    } catch {
398	      this._post({ type: 'linkedIssuePRs', prs: [] });
399	      return [];
400	    }
401	  }
402	
403	  // ─── Phase 2: Hotspot Conflict Monitor ─────────────────────────────────────
404	
405	  private async _checkConflicts(data: RunwayData) {
406	    const cwd = vscode.workspace.workspaceFolders?.[0]?.uri.fsPath;
407	    if (!cwd) return;
408	
409	    let localDirty: Set<string>;
410	    try {
411	      const { stdout } = await exec('git diff --name-only HEAD', { cwd });
412	      localDirty = new Set(stdout.trim().split('\n').filter(Boolean));
413	    } catch {
414	      return;
415	    }
416	
417	    if (!localDirty.size) {
418	      this._post({ type: 'conflictThreats', threats: [] });
419	      return;
420	    }
421	
422	    // Collect open PRs from board + linked PRs
423	    const openPRs: Array<{ owner: string; repo: string; number: number; title: string; author: string; url: string }> = [];
424	    const allBoardItems: BoardItem[] = [...Object.values(data.groups).flat(), ...(data.linkedIssuePRs ?? [])];
425	    for (const item of allBoardItems) {
426	      if (item.type === 'PULL_REQUEST' && item.state === 'OPEN' && item.repositoryOwner && item.repository) {
427	        openPRs.push({
428	          owner: item.repositoryOwner,
429	          repo: item.repository,
430	          number: item.number,
431	          title: item.title,
432	          author: item.author.login,
433	          url: item.url,
434	        });
435	      }
436	    }
437	
438	    if (!openPRs.length) {
439	      this._post({ type: 'conflictThreats', threats: [] });
440	      return;
441	    }
442	
443	    try {
444	      const prFilesMap = await fetchAllOpenPRFiles(openPRs.map((p) => ({ owner: p.owner, repo: p.repo, number: p.number })));
445	      const threats: ConflictThreat[] = [];
446	
447	      for (const pr of openPRs) {
448	        const key = `${pr.owner}/${pr.repo}#${pr.number}`;
449	        const files = prFilesMap.get(key) ?? [];
450	        for (const file of files) {
451	          if (localDirty.has(file.filename)) {
452	            threats.push({
453	              filename: file.filename,
454	              prNumber: pr.number,
455	              prTitle: pr.title,
456	              prAuthor: pr.author,
457	              prUrl: pr.url,
458	            });
459	          }
460	        }
461	      }
462	
463	      this._post({ type: 'conflictThreats', threats });
464	    } catch {
465	      // conflict check is best-effort
466	    }
467	  }
468	
469	  // ─── Phase 2: Status Bar Blocker Watchdog ──────────────────────────────────
470	
471	  private _updateStatusBar(data: RunwayData) {
472	    const allItems: BoardItem[] = [...Object.values(data.groups).flat(), ...(data.linkedIssuePRs ?? [])];
473	    const openPRs = allItems.filter((i) => i.type === 'PULL_REQUEST' && i.state === 'OPEN');
474	
475	    const ciFailures = openPRs.filter((i) => i.ciState === 'FAILURE' || i.ciState === 'ERROR');
476	    const changesRequested = openPRs.filter((i) =>
477	      i.reviews?.some((r) => r.state === 'CHANGES_REQUESTED')
478	    );
479	
480	    const total = ciFailures.length + changesRequested.length;
481	
482	    if (total === 0) {
483	      this._statusBarItem.text = '$(check) SprintHub';
484	      this._statusBarItem.backgroundColor = undefined;
485	    } else {
486	      const parts: string[] = [];
487	      if (ciFailures.length) parts.push(`${ciFailures.length} CI fail${ciFailures.length > 1 ? 's' : ''}`);
488	      if (changesRequested.length) parts.push(`${changesRequested.length} changes req`);
489	      this._statusBarItem.text = `$(warning) ${parts.join(' · ')}`;
490	      this._statusBarItem.backgroundColor = new vscode.ThemeColor('statusBarItem.warningBackground');
491	    }
492	
493	    this._statusBarItem.show();
494	
495	    // Store for use in showBlockers quick-pick
496	    (this as unknown as Record<string, unknown>)._blockerPRs = { ciFailures, changesRequested };
497	  }
498	
499	  public showBlockersQuickPick() {
500	    const stored = (this as unknown as Record<string, unknown>)._blockerPRs as
501	      | { ciFailures: BoardItem[]; changesRequested: BoardItem[] }
502	      | undefined;
503	    if (!stored) {
504	      vscode.window.showInformationMessage('SprintHub: No blocker data loaded yet.');
505	      return;
506	    }
507	
508	    const { ciFailures, changesRequested } = stored;
509	    const items: vscode.QuickPickItem[] = [];
510	
511	    if (ciFailures.length) {
512	      items.push({ label: '$(error) CI Failing', kind: vscode.QuickPickItemKind.Separator });
513	      for (const pr of ciFailures) {
514	        items.push({ label: `#${pr.number} ${pr.title}`, description: `${pr.repositoryOwner}/${pr.repository}`, detail: pr.url });
515	      }
516	    }
517	
518	    if (changesRequested.length) {
519	      items.push({ label: '$(git-pull-request) Changes Requested', kind: vscode.QuickPickItemKind.Separator });
520	      for (const pr of changesRequested) {
521	        items.push({ label: `#${pr.number} ${pr.title}`, description: `${pr.repositoryOwner}/${pr.repository}`, detail: pr.url });
522	      }
523	    }
524	
525	    if (!items.length) {
526	      vscode.window.showInformationMessage('SprintHub: All PRs are healthy!');
527	      return;
528	    }
529	
530	    void vscode.window.showQuickPick(items, { title: 'SprintHub Blockers', placeHolder: 'Select a PR to open on GitHub' }).then((selected) => {
531	      if (selected?.detail) {
532	        void vscode.env.openExternal(vscode.Uri.parse(selected.detail));
533	      }
534	    });
535	  }
536	
537	  // ─── Phase 3: Standup Markdown Generator ───────────────────────────────────
538	
539	  private async _generateStandup(viewerLogin: string) {
540	    try {
541	      const { data, markdown } = await generateStandupData(viewerLogin);
542	      this._post({ type: 'standup', data, markdown });
543	    } catch (err) {
544	      const msg = err instanceof Error ? err.message : String(err);
545	      this._post({ type: 'standup', data: { date: '', sections: [], error: msg }, markdown: `*Error generating standup: ${msg}*` });
546	    }
547	  }
548	
549	  // ─── Phase 3: Metadata Sync ─────────────────────────────────────────────────
550	
551	  private async _updateMetadata(
552	    itemId: string,
553	    owner: string,
554	    repo: string,
555	    issueNumber: number,
556	    labels?: string[],
557	    assignees?: string[]
558	  ) {
559	    try {
560	      const updated = await updateIssueMetadata(owner, repo, issueNumber, labels, assignees);
561	      this._post({ type: 'metadataUpdated', itemId, labels: updated.labels, assignees: updated.assignees });
562	    } catch (err) {
563	      const msg = err instanceof Error ? err.message : String(err);
564	      vscode.window.showErrorMessage(`SprintHub: Failed to update metadata — ${msg}`);
565	    }
566	  }
567	
568	  private async _fetchRepoLabels(owner: string, repo: string) {
569	    try {
570	      const labels = await fetchRepoLabels(owner, repo);
571	      this._post({ type: 'repoLabels', owner, repo, labels });
572	    } catch {
573	      this._post({ type: 'repoLabels', owner, repo, labels: [] });
574	    }
575	  }
576	
577	  // ─── v2 extras ───────────────────────────────────────────────────────────────
578	
579	  private async _convertDraftToReady(itemId: string, owner: string, repo: string, prNumber: number) {
580	    try {
581	      await convertDraftToReady(owner, repo, prNumber);
582	      this._post({ type: 'prReadied', itemId });
583	    } catch (err) {
584	      vscode.window.showErrorMessage(`SprintHub: ${err instanceof Error ? err.message : String(err)}`);
585	    }
586	  }
587	
588	  private async _mergePR(
589	    itemId: string,
590	    owner: string,
591	    repo: string,
592	    prNumber: number,
593	    mergeMethod: 'merge' | 'squash' | 'rebase'
594	  ) {
595	    try {
596	      await mergePR(owner, repo, prNumber, mergeMethod);
597	      this._post({ type: 'prMerged', itemId });
598	      vscode.window.showInformationMessage(`SprintHub: PR #${prNumber} merged successfully.`);
599	    } catch (err) {
600	      vscode.window.showErrorMessage(`SprintHub: ${err instanceof Error ? err.message : String(err)}`);
601	    }
602	  }
603	
604	  private async _fetchCodeowners(owner: string, repo: string) {
605	    try {
606	      const entries = await fetchCodeowners(owner, repo);
607	      this._post({ type: 'codeowners', owner, repo, entries });
608	    } catch {
609	      this._post({ type: 'codeowners', owner, repo, entries: [] });
610	    }
611	  }
612	
613	  private async _fetchSettingsOwners() {
614	    try {
615	      const owners = await fetchSettingsOwners();
616	      this._post({ type: 'settingsOwners', owners });
617	    } catch {
618	      this._post({ type: 'settingsOwners', owners: [] });
619	    }
620	  }
621	
622	  private async _fetchSettingsProjects(owner: string, ownerType: 'organization' | 'user') {
623	    try {
624	      const projects = await fetchSettingsProjects(owner, ownerType);
625	      this._post({ type: 'settingsProjects', projects });
626	    } catch {
627	      this._post({ type: 'settingsProjects', projects: [] });
628	    }
629	  }
630	
631	  // ───────────────────────────────────────────────────────────────────────────
632	
633	  private _post(message: ExtensionMessage) {
634	    this._panel.webview.postMessage(message);
635	  }
636	
637	  private _buildHtml(webview: vscode.Webview): string {
638	    const scriptUri = webview.asWebviewUri(
639	      vscode.Uri.joinPath(this._extensionUri, 'out', 'webview.js')
640	    );
641	    const stylesUri = webview.asWebviewUri(
642	      vscode.Uri.joinPath(this._extensionUri, 'out', 'styles.css')
643	    );
644	    const nonce = getNonce();
645	
646	    return /* html */ `<!DOCTYPE html>
647	<html lang="en">
648	<head>
649	  <meta charset="UTF-8">
650	  <meta name="viewport" content="width=device-width, initial-scale=1.0">
651	  <meta http-equiv="Content-Security-Policy"
652	    content="default-src 'none';
653	             img-src ${webview.cspSource} https: data:;
654	             script-src 'nonce-${nonce}';
655	             style-src ${webview.cspSource} 'unsafe-inline';">
656	  <title>SprintHub</title>
657	  <link rel="stylesheet" href="${stylesUri}">
658	</head>
659	<body>
660	  <div id="root"></div>
661	  <script nonce="${nonce}" src="${scriptUri}"></script>
662	</body>
663	</html>`;
664	  }
665	
666	  public dispose() {
667	    SprintHubPanel.currentPanel = undefined;
668	    if (this._refreshTimer) {
669	      clearInterval(this._refreshTimer);
670	    }
671	    this._statusBarItem.hide();
672	    this._panel.dispose();
673	    while (this._disposables.length) {
674	      const d = this._disposables.pop();
675	      if (d) d.dispose();
676	    }
677	  }
678	}
