476	/** Assembles a RunwayData snapshot from already-parsed groups and sprints. */
477	function assembleRunwayData(
478	  groups: Record<string, BoardItem[]>,
479	  sprintsSet: Set<string>,
480	  projectTitle: string,
481	  viewerLogin: string,
482	  rateLimit: RateLimit | undefined
483	): RunwayData {
484	  const colOrderLower = COLUMN_ORDER.map((c) => c.toLowerCase());
485	  const knownPresent = Object.keys(groups)
486	    .filter((c) => colOrderLower.includes(c.toLowerCase()))
487	    .sort((a, b) => colOrderLower.indexOf(a.toLowerCase()) - colOrderLower.indexOf(b.toLowerCase()));
488	  const extras = Object.keys(groups).filter((c) => !colOrderLower.includes(c.toLowerCase()));
489	  const columns = [...knownPresent, ...extras];
490	  const totalCount = Object.values(groups).reduce((sum, items) => sum + items.length, 0);
491	  const collator = new Intl.Collator(undefined, { numeric: true, sensitivity: 'base' });
492	  const sprints = Array.from(sprintsSet).sort((a, b) => collator.compare(b, a));
493	  return { projectTitle, columns, groups, sprints, lastUpdated: new Date().toISOString(), totalCount, viewerLogin, linkedIssuePRs: [], rateLimit };
494	}
