496	/**
497	 * Fetches all project items with progressive delivery.
498	 * `onPage` is called after each paginated response so the caller can render
499	 * partial data immediately — the board appears after the first ~100 items
500	 * rather than waiting for the full dataset to arrive.
501	 * Groups and sprints are accumulated incrementally so each page only parses
502	 * its own new nodes (O(n) total, not O(n²)).
503	 */
504	export async function fetchProjectData(
505	  owner: string,
506	  projectNumber: number,
507	  isOrg: boolean,
508	  statusFieldName: string,
509	  onPage?: (partial: RunwayData) => void
510	): Promise<RunwayData> {
511	  const token = await getToken();
512	  let projectTitle = '';
513	  let viewerLogin = '';
514	  let cursor: string | null = null;
515	
516	  type ProjectResponse = {
517	    rateLimit?: RateLimit;
518	    viewer: { login: string };
519	    org?: { projectV2: ProjectData };
520	    user?: { projectV2: ProjectData };
521	  };
522	  let lastRateLimit: RateLimit | undefined;
523	
524	  // Incremental state — only new nodes per page are parsed and appended
525	  const groups: Record<string, BoardItem[]> = {};
526	  const sprintsSet = new Set<string>();
527	
528	  do {
529	    const data: ProjectResponse = await graphql<ProjectResponse>(
530	      token,
531	      PROJECT_ITEMS_QUERY,
532	      { login: owner, number: projectNumber, isOrg, cursor }
533	    );
534	
535	    if (data.rateLimit) lastRateLimit = data.rateLimit;
536	    if (!viewerLogin) viewerLogin = data.viewer?.login ?? '';
537	
538	    const project: ProjectData | undefined = isOrg ? data.org?.projectV2 : data.user?.projectV2;
539	    if (!project) {
540	      throw new Error(`Project #${projectNumber} not found for ${owner}`);
541	    }
542	
543	    projectTitle = project.title;
544	
545	    for (const node of project.items.nodes) {
546	      const column = extractColumn(node, statusFieldName);
547	      const item = parseItem(node, column);
548	      if (!item) continue;
549	      if (!groups[column]) groups[column] = [];
550	      groups[column].push(item);
551	      if (item.sprint) sprintsSet.add(item.sprint);
552	    }
553	
554	    cursor = project.items.pageInfo.hasNextPage
555	      ? project.items.pageInfo.endCursor
556	      : null;
557	
558	    // Deliver snapshot after each page — assembleRunwayData is O(columns), not O(items)
559	    onPage?.(assembleRunwayData(groups, sprintsSet, projectTitle, viewerLogin, lastRateLimit));
560	  } while (cursor !== null);
561	
562	  return assembleRunwayData(groups, sprintsSet, projectTitle, viewerLogin, lastRateLimit);
563	}
