565	/**
566	 * Fetches linked PRs for a board after the initial data is already rendered.
567	 * Re-derives the issueByRepo index from the groups returned by fetchProjectData.
568	 */
569	export async function fetchLinkedPRsForBoard(groups: Record<string, BoardItem[]>): Promise<BoardItem[]> {
570	  const token = await getToken();
571	  const issueByRepo = new Map<string, Map<number, BoardItem>>();
572	  for (const items of Object.values(groups)) {
573	    for (const item of items) {
574	      if (item.type === 'ISSUE' && item.repositoryOwner && item.repository) {
575	        const repoKey = `${item.repositoryOwner}/${item.repository}`;
576	        if (!issueByRepo.has(repoKey)) issueByRepo.set(repoKey, new Map());
577	        issueByRepo.get(repoKey)!.set(item.number, item);
578	      }
579	    }
580	  }
581	  if (!issueByRepo.size) return [];
582	  return fetchLinkedPRsFromRepos(token, issueByRepo, groups);
583	}
