585	// Step 1: get linked PRs via closing references + timeline cross-references
586	const LINKED_PRS_QUERY = `
587	query GetLinkedPRs($owner: String!, $repo: String!, $number: Int!) {
588	  repository(owner: $owner, name: $repo) {
589	    issue(number: $number) {
590	      closingPullRequests(first: 10) {
591	        nodes {
592	          number title url state isDraft headRefName
593	          commits(last: 1) { nodes { commit { oid } } }
594	        }
595	      }
596	      timelineItems(first: 25, itemTypes: [CROSS_REFERENCED_EVENT]) {
597	        nodes {
598	          ... on CrossReferencedEvent {
599	            source {
600	              ... on PullRequest {
601	                number title url state isDraft headRefName
602	                commits(last: 1) { nodes { commit { oid } } }
603	              }
604	            }
605	          }
606	        }
607	      }
608	    }
609	  }
610	}
611	`;
