634	async function fetchCheckRunsForCommit(token: string, owner: string, repo: string, sha: string): Promise<CheckRun[]> {
635	  const url = `https://api.github.com/repos/${owner}/${repo}/commits/${sha}/check-runs?per_page=50`;
636	  const resp = await fetch(url, {
637	    headers: {
638	      Authorization: `bearer ${token}`,
639	      Accept: 'application/vnd.github+json',
640	    },
641	  });
642	  if (!resp.ok) return [];
643	  const json = (await resp.json()) as RawCheckRunResponse;
644	  return (json.check_runs ?? []).map((r) => ({
645	    name: r.name,
646	    status: r.status.toUpperCase(),
647	    conclusion: r.conclusion ? r.conclusion.toUpperCase() : null,
648	    detailsUrl: r.details_url ?? r.html_url,
649	  }));
650	}
651	
652	export async function fetchLinkedPRChecks(
653	  owner: string,
654	  repo: string,
655	  issueNumber: number
656	): Promise<LinkedPR[]> {
657	  const token = await getToken();
658	  const data = await graphql<{
659	    repository: {
660	      issue: {
661	        closingPullRequests: { nodes: RawLinkedPR[] };
662	        timelineItems: { nodes: Array<{ source?: RawLinkedPR }> };
663	      } | null;
664	    } | null;
665	  }>(token, LINKED_PRS_QUERY, { owner, repo, number: issueNumber });
666	
667	  // Merge closing PRs + timeline cross-references, deduplicate by number
668	  const closing = data.repository?.issue?.closingPullRequests?.nodes ?? [];
669	  const crossRefs = (data.repository?.issue?.timelineItems?.nodes ?? [])
670	    .map((n) => n.source)
671	    .filter((s): s is RawLinkedPR => !!s && 'number' in s);
672	
673	  const seen = new Set<number>();
674	  const merged: RawLinkedPR[] = [];
675	  for (const pr of [...closing, ...crossRefs]) {
676	    if (!seen.has(pr.number)) {
677	      seen.add(pr.number);
678	      merged.push(pr);
679	    }
680	  }
681	
682	  if (!merged.length) return [];
683	
684	  // Fetch check runs for each PR in parallel
685	  const results = await Promise.all(
686	    merged.map(async (pr): Promise<LinkedPR> => {
687	      const sha = pr.commits?.nodes?.[0]?.commit?.oid;
688	      const checkRuns = sha ? await fetchCheckRunsForCommit(token, owner, repo, sha) : [];
689	
690	      // Derive overall CI state from check runs
691	      let ciState: CIState = 'none';
692	      if (checkRuns.length) {
693	        if (checkRuns.some((r) => r.status !== 'COMPLETED')) ciState = 'PENDING';
694	        else if (checkRuns.some((r) => r.conclusion === 'FAILURE' || r.conclusion === 'TIMED_OUT')) ciState = 'FAILURE';
695	        else if (checkRuns.every((r) => r.conclusion === 'SUCCESS' || r.conclusion === 'SKIPPED' || r.conclusion === 'NEUTRAL')) ciState = 'SUCCESS';
696	        else ciState = 'PENDING';
697	      }
698	
699	      return {
700	        number: pr.number,
701	        title: pr.title,
702	        url: pr.url,
703	        state: pr.state,
704	        isDraft: pr.isDraft,
705	        headRefName: pr.headRefName,
706	        ciState,
707	        checkRuns,
708	      };
709	    })
710	  );
711	
712	  return results;
713	}
