752	// ─── Phase 2: Hotspot Monitor — open PR file lists ───────────────────────────
753	
754	export async function fetchAllOpenPRFiles(
755	  prs: Array<{ owner: string; repo: string; number: number }>
756	): Promise<Map<string, PRFile[]>> {
757	  const token = await getToken();
758	  const result = new Map<string, PRFile[]>();
759	  await Promise.all(
760	    prs.slice(0, 15).map(async ({ owner, repo, number }) => {
761	      const key = `${owner}/${repo}#${number}`;
762	      try {
