764	        const resp = await fetch(url, {
765	          headers: { Authorization: `bearer ${token}`, Accept: 'application/vnd.github+json' },
766	        });
767	        if (!resp.ok) return;
768	        const files = (await resp.json()) as RawPRFile[];
769	        result.set(key, files.map((f) => ({ filename: f.filename, additions: f.additions, deletions: f.deletions, status: f.status })));
