808	export async function generateStandupData(viewerLogin: string): Promise<{ data: StandupData; markdown: string }> {
809	  const token = await getToken();
810	  const yesterday = new Date(Date.now() - 24 * 60 * 60 * 1000).toISOString().split('T')[0];
811	  const today = new Date().toLocaleDateString('en-US', { year: 'numeric', month: 'long', day: 'numeric' });
812	
813	  const repoFromUrl = (url: string) => url.replace('https://api.github.com/repos/', '');
814	
815	  async function search(q: string): Promise<RawSearchIssue[]> {
816	    const resp = await fetch(`https://api.github.com/search/issues?q=${encodeURIComponent(q)}&per_page=30`, {
817	      headers: { Authorization: `bearer ${token}`, Accept: 'application/vnd.github+json' },
818	    });
819	    if (!resp.ok) return [];
820	    const json = (await resp.json()) as { items: RawSearchIssue[] };
821	    return json.items ?? [];
822	  }
823	
824	  async function fetchCommentedItems(): Promise<RawSearchIssue[]> {
825	    const resp = await fetch(
826	      `https://api.github.com/users/${viewerLogin}/events?per_page=100`,
827	      { headers: { Authorization: `bearer ${token}`, Accept: 'application/vnd.github+json' } }
828	    );
829	    if (!resp.ok) return [];
830	    const events = (await resp.json()) as RawGitHubEvent[];
831	
832	    const seenUrls = new Set<string>();
833	    const items: RawSearchIssue[] = [];
834	
835	    for (const event of events) {
836	      // Events are newest-first — stop once we're past the 24h window
837	      if (event.created_at < yesterday) break;
838	
839	      const isMyComment =
840	        (event.type === 'IssueCommentEvent' && event.payload.action === 'created') ||
841	        (event.type === 'PullRequestReviewCommentEvent' && event.payload.action === 'created') ||
842	        event.type === 'PullRequestReviewEvent';
843	      if (!isMyComment) continue;
844	
845	      const target = event.payload.issue ?? event.payload.pull_request;
846	      if (!target || seenUrls.has(target.html_url)) continue;
847	      seenUrls.add(target.html_url);
848	
849	      items.push({
850	        number: target.number,
851	        title: target.title,
852	        html_url: target.html_url,
853	        repository_url: `https://api.github.com/repos/${event.repo.name}`,
854	        pull_request: (event.payload.pull_request ?? event.payload.issue?.pull_request) ? { merged_at: null } : undefined,
855	      });
856	    }
857	    return items;
858	  }
859	
860	  const [mergedPRs, openPRs, commentedItems] = await Promise.all([
861	    search(`is:pr is:merged author:${viewerLogin} merged:>${yesterday}`),
862	    search(`is:pr is:open author:${viewerLogin} updated:>${yesterday}`),
863	    fetchCommentedItems(),
864	  ]);
865	
866	  // Remove items already listed in merged/open from the commented section
867	  const listedUrls = new Set([...mergedPRs, ...openPRs].map((i) => i.html_url));
868	  const uniqueCommented = commentedItems.filter((i) => !listedUrls.has(i.html_url));
869	
870	  function toRepoGroups(items: RawSearchIssue[]): StandupRepoGroup[] {
871	    const map = new Map<string, StandupRepoGroup['items']>();
872	    for (const item of items) {
873	      const repo = repoFromUrl(item.repository_url);
874	      if (!map.has(repo)) map.set(repo, []);
875	      map.get(repo)!.push({ number: item.number, title: item.title, url: item.html_url, isPR: !!item.pull_request });
876	    }
877	    return Array.from(map.entries()).map(([repo, its]) => ({ repo, items: its }));
878	  }
879	
880	  const rawSections: Array<{ key: string; icon: string; title: string; items: RawSearchIssue[] }> = [
881	    { key: 'merged',    icon: '✅', title: 'Merged PRs',    items: mergedPRs },
882	    { key: 'open',      icon: '🔄', title: 'Open PRs',      items: openPRs },
883	    { key: 'commented', icon: '💬', title: 'Commented on',  items: uniqueCommented },
884	  ];
885	
886	  const sections: StandupSection[] = rawSections
887	    .filter((s) => s.items.length > 0)
888	    .map((s) => ({ key: s.key, icon: s.icon, title: s.title, groups: toRepoGroups(s.items) }));
889	
890	  const data: StandupData = { date: today, sections };
891	
892	  // Generate markdown from structured data (used for the copy-as-markdown button)
893	  const lines: string[] = [`## Daily Standup — ${today}`, ''];
894	  if (sections.length === 0) {
895	    lines.push('*No activity found in the last 24 hours.*', '');
896	  } else {
897	    for (const section of sections) {
898	      lines.push(`### ${section.icon} ${section.title}`);
899	      for (const group of section.groups) {
900	        lines.push(`**${group.repo}**`);
901	        for (const item of group.items) {
902	          lines.push(`- [#${item.number} ${item.title}](${item.url})`);
903	        }
904	      }
905	      lines.push('');
906	    }
907	  }
908	  lines.push('*Generated by SprintHub*');
909	
910	  return { data, markdown: lines.join('\n') };
911	}
