142	function useDebounce<T>(value: T, delay: number): T {
143	  const [debounced, setDebounced] = useState(value);
144	  useEffect(() => {
145	    const id = setTimeout(() => setDebounced(value), delay);
146	    return () => clearTimeout(id);
147	  }, [value, delay]);
148	  return debounced;
149	}
