11	export interface GHMilestone {
12	  title: string;
13	  number: number;
14	  dueOn?: string | null;
15	}
16	
17	export type CIState = 'SUCCESS' | 'FAILURE' | 'PENDING' | 'ERROR' | 'EXPECTED' | 'none';
18	export type ReviewState = 'APPROVED' | 'CHANGES_REQUESTED' | 'COMMENTED' | 'DISMISSED' | 'PENDING';
19	
20	export interface CheckRun {
21	  name: string;
22	  status: string; // QUEUED | IN_PROGRESS | COMPLETED | WAITING | REQUESTED | PENDING
23	  conclusion: string | null; // SUCCESS | FAILURE | NEUTRAL | CANCELLED | SKIPPED | TIMED_OUT | ACTION_REQUIRED
24	  detailsUrl?: string;
25	}
26	
27	export interface LinkedPR {
28	  number: number;
29	  title: string;
30	  url: string;
31	  state: string;
32	  isDraft: boolean;
33	  headRefName: string;
