77	}
78	
79	export interface RunwayData {
80	  projectTitle: string;
81	  columns: string[];
82	  groups: Record<string, BoardItem[]>;
83	  sprints: string[];
84	  lastUpdated: string;
85	  totalCount: number;
86	  viewerLogin: string;
87	  /** Open PRs linked to board issues via closingPullRequests (Closes #N syntax) */
88	  linkedIssuePRs: BoardItem[];
89	  rateLimit?: RateLimit;
90	}
91	
