96	  statusFieldName: string;
97	  refreshInterval: number;
98	  liquidGlass: boolean;
99	  theme: 'dark' | 'light';
100	  colorBlind: boolean;
101	}
102	
103	// Phase 1 — File-level deep linking
104	export interface PRFile {
105	  filename: string;
106	  patch?: string;
107	  additions: number;
108	  deletions: number;
109	  status: string; // added | modified | removed | renamed | copied
110	}
111	
112	// Phase 2 — Hotspot conflict detection
113	export interface ConflictThreat {
114	  filename: string;
115	  prNumber: number;
116	  prTitle: string;
117	  prAuthor: string;
118	  prUrl: string;
119	}
120	
121	// Phase 3 — Available repo labels for metadata editor
122	export interface RepoLabel {
123	  name: string;
124	  color: string;
125	}
126	
127	// Phase 3 — Structured standup data
128	export interface StandupItem {
129	  number: number;
130	  title: string;
131	  url: string;
132	  isPR: boolean;
133	}
134	
135	export interface StandupRepoGroup {
136	  repo: string; // "owner/repo"
137	  items: StandupItem[];
138	}
139	
