141	  key: string;
142	  icon: string;
143	  title: string;
144	  groups: StandupRepoGroup[];
145	}
146	
147	export interface StandupData {
148	  date: string;
149	  sections: StandupSection[];
150	  error?: string;
151	}
152	
153	// Messages: extension → webview
154	export type ExtensionMessage =
155	  | { type: 'loading' }
156	  | { type: 'refreshing' }
157	  | { type: 'dataComplete' }
158	  | { type: 'data'; payload: RunwayData }
159	  | { type: 'error'; message: string }
160	  | { type: 'config'; payload: RunwayConfig }
161	  | { type: 'linkedPRs'; itemId: string; prs: LinkedPR[] }
162	  | { type: 'itemBody'; itemId: string; body: string | null; updatedAt: string }
163	  // Phase 1
164	  | { type: 'prFiles'; prKey: string; files: PRFile[] }
165	  // Phase 2
166	  | { type: 'conflictThreats'; threats: ConflictThreat[] }
167	  | { type: 'linkedIssuePRs'; prs: BoardItem[] }
168	  // Phase 3
169	  | { type: 'standup'; data: StandupData; markdown: string }
170	  | { type: 'metadataUpdated'; itemId: string; labels: GHLabel[]; assignees: GHUser[] }
171	  | { type: 'repoLabels'; owner: string; repo: string; labels: GHLabel[] }
172	  // v2 extras
173	  | { type: 'prReadied'; itemId: string }
174	  | { type: 'prMerged'; itemId: string }
175	  | { type: 'codeowners'; owner: string; repo: string; entries: Array<{ pattern: string; owners: string[] }> }
176	  // Settings pickers
177	  | { type: 'settingsOwners'; owners: Array<{ login: string; ownerType: 'organization' | 'user' }> }
178	  | { type: 'settingsProjects'; projects: Array<{ number: number; title: string }> };
179	
180	// Messages: webview → extension
181	export type WebviewMessage =
182	  | { type: 'refresh' }
183	  | { type: 'openUrl'; url: string }
184	  | { type: 'getConfig' }
185	  | { type: 'updateConfig'; payload: RunwayConfig }
186	  | { type: 'fetchLinkedPRs'; itemId: string; owner: string; repo: string; issueNumber: number }
187	  | { type: 'fetchBody'; itemId: string; owner: string; repo: string; number: number; isIssue: boolean; updatedAt: string }
188	  // Phase 1
189	  | { type: 'workOnThis'; branchName: string; owner: string; repo: string }
190	  | { type: 'fetchPRFiles'; prKey: string; owner: string; repo: string; prNumber: number }
191	  | { type: 'openPRFile'; owner: string; repo: string; prNumber: number; filename: string; patch?: string }
192	  // Phase 3
193	  | { type: 'generateStandup'; viewerLogin: string }
194	  | { type: 'updateMetadata'; itemId: string; owner: string; repo: string; issueNumber: number; labels?: string[]; assignees?: string[] }
195	  | { type: 'fetchRepoLabels'; owner: string; repo: string }
196	  // v2 extras
197	  | { type: 'convertDraftToReady'; itemId: string; owner: string; repo: string; prNumber: number }
198	  | { type: 'mergePR'; itemId: string; owner: string; repo: string; prNumber: number; mergeMethod: 'merge' | 'squash' | 'rebase' }
199	  | { type: 'fetchCodeowners'; owner: string; repo: string }
200	  // Settings pickers
201	  | { type: 'fetchSettingsOwners' }
202	  | { type: 'fetchSettingsProjects'; owner: string; ownerType: 'organization' | 'user' };
