  isDraft?: boolean;
  additions?: number;
  deletions?: number;
  headRefName?: string;
  ciState?: CIState;
  reviews?: ReviewInfo[];
  reviewRequests?: GHUser[];
  closingIssueNumbers?: number[]; // issue numbers this PR closes
}

export interface RateLimit {
